[28772] = {id=28772,name="Lions for Lambs",level=1,requiredLevel=1,faction="alliance",expansion=3,zoneID=6170,description="The invading orcs aren't fools. They are sizing us up, making sure that when they attack it will be to their advantage. In the forest, to the northwest, are Blackrock spies. They peer at us through spyglasses, watching our every move - waiting. I want you take the fight to them! Kill the Blackrock spies! We must show them that we know they are watching us and that we are prepared!",starts={{npcID=197,x=0.48,y=0.42,zoneID=12},{npcID=197,x=0.332,y=0.532,zoneID=6170}},ends={{npcID=197,x=0.48,y=0.42,zoneID=12},{npcID=197,x=0.332,y=0.532,zoneID=6170}},coords={x=0.48,y=0.42,source="quest_giver",zoneID=12},questType="standard"},
