[28778] = {id=28778,name="Broken Boar Figurine",level=10,requiredLevel=10,faction="none",expansion=3,zoneID=3805,mapID=2437,description="This badly broken figurine was discarded by its last owner. However, with the right materials and your skill in jewelcrafting, it could be completely restored.",questType="standard"},
[28780] = {id=28780,name="Join the Battle!",level=1,requiredLevel=1,faction="alliance",expansion=3,zoneID=6170,description="I received an urgent message from Sergeant Willem . Turns out that the Blackrock orcs have hired goblin assassins. They ambushed our battalion behind the abbey. Willem has asked me to send him a hero. You have to go help them, ! Find Sergeant Willem north of the abbey at the command tent. Go!",starts={{npcID=197,x=0.48,y=0.42,zoneID=12},{npcID=197,x=0.332,y=0.532,zoneID=6170},{npcID=43278,x=0.346,y=0.548,zoneID=6170}},ends={{npcID=823,x=0.488,y=0.384,zoneID=12},{npcID=823,x=0.356,y=0.4,zoneID=6170}},coords={x=0.48,y=0.42,source="quest_giver",zoneID=12},questType="standard"},
[28781] = {id=28781,name="Targets of Opportunity",level=30,requiredLevel=30,faction="both",expansion=3,zoneID=5396,description="We were part of a clandestine operation put together by Prince Nadun of Ramkahen. We lost most of our unit during an ambush and we're now unable to finish our mission. Should you be up for it, I can arrange for a sizable reward for you. We were instructed to take out any targets of opportunity that would damage the enemy's military infrastructure. We've spotted General Husam and two of his captains up ahead. Slaying them for us will be a great favor for Ramkahen.",starts={{npcID=50038,x=0.318,y=0.168,zoneID=5034},{npcID=50038,x=0.318,y=0.168,zoneID=5396}},ends={{npcID=50038,x=0.318,y=0.168,zoneID=5034},{npcID=50038,x=0.318,y=0.168,zoneID=5396}},coords={x=0.318,y=0.168,source="quest_giver",zoneID=5034},questType="dungeon"},
[28782] = {id=28782,name="A Bird of Legend",level=15,requiredLevel=15,faction="both",expansion=3,zoneID=618,description="Local legend tells of a mighty owl that circles the mountaintops like death on wings. They named her Deathwing. Soon afterwards, they were told that that name was already taken. So they settled on a moniker that evoked a similar sense of horror and dread: Hell-Hoot . Hell-Hoot can be found atop the mountain to the southwest of our smoking pit. Silence the infernal nocturnal... so we can eat her!",ends={{npcID=49537,x=0.56,y=0.282,zoneID=618}},questType="standard"},
[28783] = {id=28783,name="The Source of Their Power",level=30,requiredLevel=30,faction="both",expansion=3,zoneID=5396,description="We managed to do extensive scouting before our crew was ambushed. We discovered that Deathwing's envoy, Siamat , is giving the Neferset their newfound power. They claim it has restored them to the greatness of old, but something else has happened. Their very souls have been corrupted. As one of the four winds, Siamat is incredibly powerful. But that power has been drained considerably by this process. Strike now, while it is possible for you to slay him and bring an end to this madness.",starts={{npcID=50038,x=0.318,y=0.168,zoneID=5034},{npcID=50038,x=0.318,y=0.168,zoneID=5396}},ends={{npcID=50038,x=0.318,y=0.168,zoneID=5034},{npcID=50038,x=0.318,y=0.168,zoneID=5396}},coords={x=0.318,y=0.168,source="quest_giver",zoneID=5034},questType="dungeon"},
[28784] = {id=28784,name="Join the Battle!",level=1,requiredLevel=1,faction="alliance",expansion=3,zoneID=6170,description="I received an urgent message from Sergeant Willem . Turns out that the Blackrock orcs have hired goblin assassins. They ambushed our battalion behind the abbey. Willem has asked me to send him a hero. You have to go help them, ! Find Sergeant Willem north of the abbey at the command tent. Go!",starts={{npcID=197,x=0.48,y=0.42,zoneID=12},{npcID=198,x=0.496,y=0.394,zoneID=12},{npcID=197,x=0.332,y=0.532,zoneID=6170},{npcID=198,x=0.386,y=0.436,zoneID=6170}},ends={{npcID=823,x=0.488,y=0.384,zoneID=12},{npcID=823,x=0.356,y=0.4,zoneID=6170}},coords={x=0.48,y=0.42,source="quest_giver",zoneID=12},questType="standard"},
