[28791] = {id=28791,name="They Sent Assassins",level=1,requiredLevel=1,faction="alliance",expansion=3,zoneID=6170,description="Have you ever seen a goblin, ? They're wretched little monsters that love only two things: gold and themselves. The Blackrock orcs have enlisted the aid of goblin assassins to kill our soldiers. If you look to the field in the north you can barely make out their silhouettes, sneaking about in the grass. I need you to head out there and kill every goblin that you see. They need to learn that nobody messes with the Alliance!",starts={{npcID=823,x=0.488,y=0.384,zoneID=12},{npcID=823,x=0.356,y=0.4,zoneID=6170}},ends={{npcID=823,x=0.488,y=0.384,zoneID=12},{npcID=823,x=0.356,y=0.4,zoneID=6170}},coords={x=0.488,y=0.384,source="quest_giver",zoneID=12},questType="standard"},
