[28805] = {id=28805,name="The Eye of the Storm",level=30,requiredLevel=30,faction="horde",expansion=3,zoneID=1637,description="Greetings, . Yes, you are known to the Earthen Ring by name. Your exploits and accomplishments are many. Azeroth already stands in your debt, and yet again she is in need of her heroes. I am but a messenger. A familiar presence seeks audience with you. Peer into the Waters of Farseeing and behold the fate of our world.",starts={{npcID=45244,x=0.504,y=0.382,zoneID=1637}},ends={{npcID=45244,x=0.504,y=0.382,zoneID=1637}},coords={x=0.504,y=0.382,source="quest_giver",zoneID=1637},questType="standard"},
[28806] = {id=28806,name="Fear No Evil",level=1,requiredLevel=1,faction="alliance",expansion=3,zoneID=6170,description="Have you embraced the Holy Light yet, ? It is through the Holy Light that we are saved! It is through the Holy Light that I am able to heal these overly demanding soldiers! And it is through the Holy Light that you will be able to venture out into the field to the north and rescue our fallen brothers! Take this prayer book with you into the field and cast the Light's healing touch on the injured.",starts={{npcID=951,x=0.486,y=0.38,zoneID=12},{npcID=951,x=0.35,y=0.386,zoneID=6170}},ends={{npcID=951,x=0.486,y=0.38,zoneID=12},{npcID=951,x=0.35,y=0.386,zoneID=6170}},coords={x=0.486,y=0.38,source="quest_giver",zoneID=12},questType="standard"},
[28808] = {id=28808,name="Fear No Evil",level=1,requiredLevel=1,faction="alliance",expansion=3,zoneID=6170,description="Have you embraced the Holy Light yet, ? It is through the Holy Light that we are saved! It is through the Holy Light that I am able to heal these overly demanding soldiers! And it is through the Holy Light that you will be able to venture out into the field to the north and rescue our fallen brothers! Take this prayer book with you into the field and cast the Light's healing touch on the injured.",starts={{npcID=951,x=0.486,y=0.38,zoneID=12},{npcID=951,x=0.35,y=0.386,zoneID=6170}},ends={{npcID=951,x=0.486,y=0.38,zoneID=12},{npcID=951,x=0.35,y=0.386,zoneID=6170}},coords={x=0.486,y=0.38,source="quest_giver",zoneID=12},questType="standard"},
