[28814] = {id=28814,name="Followers and Leaders",level=30,requiredLevel=30,faction="both",expansion=3,zoneID=5088,description="The documents detail the arrival of High Priestess Azil to the depths of the Stonecore . Azil is described as a high-ranking member of the Twilight Council. Additionally, her entourage of over a hundred devout followers is preparing for an unholy ritual of unforeseen darkness. Sounds like an event you need to put a stop to.",questType="dungeon"},
[28816] = {id=28816,name="To the Depths",level=30,requiredLevel=30,faction="horde",expansion=3,zoneID=14,description="The Earthen Ring has identified the watery realm of Vashj'ir as a source of the adversary's destructive energies. It is still uncertain what dangers might be faced there. Any information you could gather would be of great value. The Horde is sending warships to the region as we speak. To gain passage, speak to Commander Thorak at Bladefist Bay. May the spirits guide you, .",starts={{npcID=45244,x=0.504,y=0.382,zoneID=1637}},ends={{npcID=41621,x=0.558,y=0.122,zoneID=14}},coords={x=0.504,y=0.382,source="quest_giver",zoneID=1637},questType="standard"},
[28817] = {id=28817,name="The Rear is Clear",level=1,requiredLevel=1,faction="alliance",expansion=3,zoneID=6170,description="Excellent work, ! The rear is now officially clear. We'll take care of the stragglers. I want you to go back to Marshal McBride , standing in front of Northshire Abbey, south of here, and let him know that the goblin situation is under control. Farewell, .",starts={{npcID=823,x=0.488,y=0.384,zoneID=12},{npcID=823,x=0.356,y=0.4,zoneID=6170}},ends={{npcID=197,x=0.48,y=0.42,zoneID=12},{npcID=197,x=0.332,y=0.532,zoneID=6170}},coords={x=0.488,y=0.384,source="quest_giver",zoneID=12},questType="standard"},
[28818] = {id=28818,name="The Rear is Clear",level=1,requiredLevel=1,faction="alliance",expansion=3,zoneID=6170,description="Excellent work, ! The rear is now officially clear. We'll take care of the stragglers. I want you to go back to Marshal McBride , standing in front of Northshire Abbey, south of here, and let him know that the goblin situation is under control. Farewell, .",starts={{npcID=823,x=0.488,y=0.384,zoneID=12},{npcID=823,x=0.356,y=0.4,zoneID=6170}},ends={{npcID=197,x=0.48,y=0.42,zoneID=12},{npcID=197,x=0.332,y=0.532,zoneID=6170}},coords={x=0.488,y=0.384,source="quest_giver",zoneID=12},questType="standard"},
