[29013] = {id=29013,name="Candy Bucket",level=10,requiredLevel=10,faction="alliance",expansion=3,zoneID=406,mapID=65,starts={{npcID=208176,x=0.315,y=0.607,mapID=65}},ends={{npcID=208176,x=0.315,y=0.607,mapID=65}},coords={x=0.315,y=0.607,source="quest_giver",mapID=65},questType="standard"},
[29014] = {id=29014,name="Candy Bucket",level=10,requiredLevel=10,faction="both",expansion=3,zoneID=440,mapID=71,starts={{npcID=208177,x=0.557,y=0.609,mapID=71}},ends={{npcID=208177,x=0.557,y=0.609,mapID=71}},coords={x=0.557,y=0.609,source="quest_giver",mapID=71},questType="standard"},
[29015] = {id=29015,name="Miner's Fortune",level=5,requiredLevel=5,faction="horde",expansion=3,zoneID=17,description="Hey , you interested in treasure? I knew that would get your attention. Word from the river dock here is that one of the miners in the Venture Company's Boulder Lode mine just northeast of here discovered an emerald the size of your fist. I know a few buyers who'd be interested in getting their hands on something like that, and I'd be willing to go half and half on its sale. You in?",starts={{npcID=34674,x=0.626,y=0.17,zoneID=17}},ends={{npcID=34674,x=0.626,y=0.17,zoneID=17}},coords={x=0.626,y=0.17,source="quest_giver",zoneID=17},questType="standard"},
[29016] = {id=29016,name="Candy Bucket",level=10,requiredLevel=10,faction="both",expansion=3,zoneID=10833,mapID=1527,starts={{npcID=208178,x=0.266,y=0.073,mapID=249},{npcID=208178,x=0.266,y=0.073,mapID=1527}},ends={{npcID=208178,x=0.266,y=0.073,mapID=249},{npcID=208178,x=0.266,y=0.073,mapID=1527}},coords={x=0.266,y=0.073,source="quest_giver",mapID=1527},questType="standard"},
[29017] = {id=29017,name="Candy Bucket",level=10,requiredLevel=10,faction="both",expansion=3,zoneID=5034,mapID=249,starts={{npcID=208179,x=0.547,y=0.33,mapID=249}},ends={{npcID=208179,x=0.547,y=0.33,mapID=249}},coords={x=0.547,y=0.33,source="quest_giver",mapID=249},questType="standard"},
[29018] = {id=29018,name="Candy Bucket",level=10,requiredLevel=10,faction="both",expansion=3,zoneID=490,mapID=78,starts={{npcID=208180,x=0.552,y=0.621,mapID=78}},ends={{npcID=208180,x=0.552,y=0.621,mapID=78}},coords={x=0.552,y=0.621,source="quest_giver",mapID=78},questType="standard"},
[29019] = {id=29019,name="Candy Bucket",level=10,requiredLevel=10,faction="horde",expansion=3,zoneID=5042,mapID=207,starts={{npcID=208181,x=0.512,y=0.5,mapID=207}},ends={{npcID=208181,x=0.512,y=0.5,mapID=207}},coords={x=0.512,y=0.5,source="quest_giver",mapID=207},questType="standard"},
[29020] = {id=29020,name="Candy Bucket",level=10,requiredLevel=10,faction="alliance",expansion=3,zoneID=5042,mapID=207,starts={{npcID=208183,x=0.474,y=0.517,mapID=207}},ends={{npcID=208183,x=0.474,y=0.517,mapID=207}},coords={x=0.474,y=0.517,source="quest_giver",mapID=207},questType="standard"},
[29021] = {id=29021,name="Samophlange",level=5,requiredLevel=5,faction="horde",expansion=3,zoneID=17,description="The Venture Company have a small research facility west of here, just past the Sludge Fen. I don't know very much about what they're doing, but did manage to discover that they're experimenting with something called a \"samophlange\". Now what the heck is a samophlange? Well, whatever it is, I want to examine it, so I need someone to go get it. I obtained a copy of their control system operating manual, you should be able to figure out how to disengage the samophlange from it.",starts={{npcID=3442,x=0.622,y=0.174,zoneID=17}},ends={{npcID=4141,x=0.503,y=0.257,zoneID=17}},coords={x=0.622,y=0.174,source="quest_giver",zoneID=17},questType="standard"},
[29022] = {id=29022,name="Samophlange",level=5,requiredLevel=5,faction="horde",expansion=3,zoneID=17,description="The three control valves are currently opened. The various readings on the control panel lead you to presume that they must be shut off before the apparatus can be shut off.",starts={{npcID=4141,x=0.503,y=0.257,zoneID=17}},ends={{npcID=4141,x=0.503,y=0.257,zoneID=17}},coords={x=0.503,y=0.257,source="quest_giver",zoneID=17},questType="standard"},
[29023] = {id=29023,name="Samophlange",level=5,requiredLevel=5,faction="horde",expansion=3,zoneID=17,description="With the apparatus deactivated, the control panel can be opened up and the samophlange removed from the console. With everything else in place, all that is left is to acquire the key to unlock the console.",starts={{npcID=4141,x=0.503,y=0.257,zoneID=17}},ends={{npcID=4141,x=0.503,y=0.257,zoneID=17}},coords={x=0.503,y=0.257,source="quest_giver",zoneID=17},questType="standard"},
[29024] = {id=29024,name="Samophlange",level=5,requiredLevel=5,faction="horde",expansion=3,zoneID=17,description="Pulling open the face of the control console reveals a dense jumble of wires, tubing and other strange mechanical objects--most of which seem to serve no practical purpose. Pushing them aside and digging deeper into the console, you find the samophlange . A tug removes it from its housing.",starts={{npcID=4141,x=0.503,y=0.257,zoneID=17}},ends={{npcID=3442,x=0.622,y=0.174,zoneID=17}},coords={x=0.503,y=0.257,source="quest_giver",zoneID=17},questType="standard"},
[29026] = {id=29026,name="Wenikee Boltbucket",level=5,requiredLevel=5,faction="horde",expansion=3,zoneID=17,description="I think I really put my foot into that one - it looks like I might have knocked one of the load-bearing fluxors into the spokes of the deregulator gear. We can fix this, easy. I know an expert on triple-expansion piston drives who would love to get her hands on a samophlange. Take the broken samophlange to Wenikee Boltbucket , just south of Mor'shan Rampart, she'll patch 'er right up. Hey, no need to walk - this gives me the perfect opportunity to test my personal people porter device!",starts={{npcID=34674,x=0.626,y=0.17,zoneID=17}},ends={{npcID=9316,x=0.442,y=0.248,zoneID=17}},coords={x=0.626,y=0.17,source="quest_giver",zoneID=17},questType="standard"},
[29027] = {id=29027,name="Nugget Slugs",level=5,requiredLevel=5,faction="horde",expansion=3,zoneID=17,description="I want to fix this samophlange, but to do that I'm going to need some supplies. I ran out of seventeen-point-five gauge nugget slugs and I'm going to need a bunch of those for the work ahead. Unfortunately, the closest place to get them is the Burning Blade farm to the southwest. The place will be heavily guarded, so be careful, but the samophlange just might be worth the risk. Search the tool buckets, then return to me when you've gathered enough nugget slugs .",starts={{npcID=9316,x=0.442,y=0.248,zoneID=17}},ends={{npcID=9316,x=0.442,y=0.248,zoneID=17}},coords={x=0.442,y=0.248,source="quest_giver",zoneID=17},questType="standard"},
[29032] = {id=29032,name="Get Them While They're Young",level=15,requiredLevel=15,faction="alliance",expansion=3,zoneID=618,description="I can teach you to ride a Winterspring frostsaber, but it takes time and dedication. For this to work, both saber and rider must be highly trained and both must share a bond of deep trust. The cubs are only receptive to this training if they're introduced to their riders at a young age. Some of the cubs in the dens surrounding Frostsaber Rock are at the proper age to begin their training. If you help me gather the most promising of those cubs, I'll allow you to begin training with your own cub.",starts={{npcID=10618,x=0.466,y=0.176,zoneID=618}},ends={{npcID=10618,x=0.466,y=0.176,zoneID=618}},coords={x=0.466,y=0.176,source="quest_giver",zoneID=618},questType="standard"},
[29034] = {id=29034,name="They Grow Up So Fast",level=15,requiredLevel=15,faction="alliance",expansion=3,zoneID=618,description="I think this little fellow will be a good match for you. This cub is going to require a lot of attention to ensure that he grows up strong and healthy. You should check up on your cub at least once each day. Feeding and caring for your Winterspring cub is the best way to build a bond of trust with him. As your cub grows, he will shed his old whiskers and grow new ones appropriate to his size. Once your cub has shed twenty whiskers, bring him back to me along with some materials for your saddle.",starts={{npcID=10618,x=0.466,y=0.176,zoneID=618}},ends={{npcID=10618,x=0.466,y=0.176,zoneID=618}},coords={x=0.466,y=0.176,source="quest_giver",zoneID=618},questType="standard"},
[29035] = {id=29035,name="A Cub's Cravings",level=15,requiredLevel=15,faction="alliance",expansion=3,zoneID=616,description="Your Winterspring cub looks at you and licks its lips. The little cat must be hungry and it's up to you to find a suitable meal for your charge. Rivern Frostwind mentioned keeping some shardtooth bear meat on hand for feeding his frostsaber cubs. Perhaps your cub would enjoy some fresh shardtooth meat of its own. Various kinds of shardtooth bears can be found all over Winterspring .",questType="standard"},
[29036] = {id=29036,name="Honor the Flame",level=1,requiredLevel=1,faction="both",expansion=3,zoneID=5042,description="The Midsummer Fire Festival is a time to honor the elements. The element of fire stirs passion within us all. Many times, that passion pours out into aggressive actions. But here, in this land, we focus our passion on reverence. We will honor the flame as tradition dictates. Will you honor the flame with us, ?",starts={{npcID=51698,x=0.494,y=0.514,zoneID=5042}},ends={{npcID=208188,x=0.494,y=0.514,zoneID=5042}},coords={x=0.494,y=0.514,source="quest_giver",zoneID=5042},questType="standard"},
[29037] = {id=29037,name="'Borrowing' From the Winterfall",level=15,requiredLevel=15,faction="alliance",expansion=3,zoneID=618,description="Your cub looks at you expectantly. What could it want now? The little cat licks its lips. It must be meal time again! As the cub's surrogate you're responsible for providing meat until it can hunt on its own. But what if you let someone else do the hunting? The Winterfall furbolg of Winterspring usually have a lot of smoked meat on hand in both of their camps. Surely, they wouldn't miss a few pieces and your cub would get to try something new.",questType="standard"},
[29038] = {id=29038,name="Hunting Practice",level=15,requiredLevel=15,faction="alliance",expansion=3,zoneID=618,description="Your Winterspring cub paws playfully at your hands. Without any playmates, the cub has few chances to practice its hunting skills. Perhaps you should take your cub hunting for the small arctic hares that burrow in the snow of northern Winterspring . Bring your cub close to the mounds of snow covering the hare burrows and wait for the cub's instincts to take over.",questType="standard"},
[29040] = {id=29040,name="Cub's First Toy",level=15,requiredLevel=15,faction="alliance",expansion=3,zoneID=618,description="The winterspring cub plays with a small tuft of fur from a large animal, batting the discarded hair about. While your cub looks like it's enjoying the new game, you wonder if it might get more enjoyment from a proper cat toy. With a little bit of leather from a yeti pelt and some feathers from crazed moonkin, you could make a respectable toy. You'll need a hide from the yeti in the Ice Thistle Hills southeast of Everlook and feathers from the moonkin at the Hidden Grove or Owl Wing Thicket.",questType="standard"},
[29054] = {id=29054,name="Stink Bombs Away!",level=10,requiredLevel=10,faction="alliance",expansion=3,zoneID=12,description="Greetings, ! I hope Hallow's End is treating you well. Bah, enough of the small talk... Let's get down to business. Undercity. They have employed Hags and foul magic to launch petty attacks on our town. Some may say, ignore the childish Horde. I say, let's show them! Speak to my sister, Gertrude, and she will send you on your way to toss some stink bombs in Undercity.",starts={{npcID=51934,x=0.322,y=0.508,zoneID=12}},ends={{npcID=51934,x=0.322,y=0.508,zoneID=12}},coords={x=0.322,y=0.508,source="quest_giver",zoneID=12},questType="standard"},
[29066] = {id=29066,name="Good News... and Bad News",level=30,requiredLevel=30,faction="both",expansion=3,zoneID=616,description="Matoclaw will want to know what happened here. She's waiting for you back at the Grove of Aessina.>",starts={{npcID=39928,x=0.19,y=0.37,zoneID=616}},ends={{npcID=39928,x=0.19,y=0.37,zoneID=616}},coords={x=0.19,y=0.37,source="quest_giver",zoneID=616},questType="standard"},
[29067] = {id=29067,name="Potion Master",level=1,requiredLevel=1,faction="both",expansion=3,zoneID=1657,description="Potions, potions, potions. Can I teach you about potions! You're going to have to bring me samples of your work, so I know you're ready. Remember , you can only learn ONE specialization, so if you complete your potion training, then elixir and transmutation specialization will no longer be available.",starts={{npcID=3009,x=0.468,y=0.336,zoneID=1638},{npcID=3347,x=0.556,y=0.458,zoneID=1637},{npcID=5177,x=0.666,y=0.55,zoneID=1537},{npcID=5499,x=0.556,y=0.858,zoneID=1519}},ends={{npcID=3347,x=0.556,y=0.458,zoneID=1637},{npcID=5499,x=0.556,y=0.858,zoneID=1519},{npcID=4160,x=0.54,y=0.382,zoneID=1657}},coords={x=0.468,y=0.336,source="quest_giver",zoneID=1638},questType="standard"},
[29071] = {id=29071,name="Make Haste to Stormwind!",level=10,requiredLevel=10,faction="alliance",expansion=3,zoneID=6611,mapID=501,starts={{npcID=208316,x=0.75,y=0.887,mapID=118},{npcID=208316,x=0.377,y=0.628,mapID=118}},ends={{npcID=208316,x=0.75,y=0.887,mapID=118},{npcID=208316,x=0.377,y=0.628,mapID=118}},coords={x=0.75,y=0.887,source="quest_giver",mapID=501},questType="standard"},
[29074] = {id=29074,name="A Season for Celebration",level=10,requiredLevel=10,faction="alliance",expansion=3,zoneID=12,description="Merry met, ! Hallow's End is a time for celebration and reflection, though many of us have forgotten why. Indeed some aspects of the festival, like the Wickerman, had been lost to time... until the Gilneans returned to the Alliance fold. Travel outside the gates of Stormwind and speak to Celestine of the Harvest . She can tell you more about the Wickerman ceremony.",starts={{npcID=18927,x=0.616,y=0.74,zoneID=1519},{npcID=19148,x=0.308,y=0.632,zoneID=1537},{npcID=19172,x=0.578,y=0.49,zoneID=1537},{npcID=19148,x=0.648,y=0.73,zoneID=6507},{npcID=19172,x=0.64,y=0.74,zoneID=6507},{npcID=19171,x=0.294,y=0.282,zoneID=457},{npcID=19171,x=0.52,y=0.422,zoneID=3557},{npcID=19173,x=0.446,y=0.526,zoneID=1657},{npcID=20102,x=0.69,y=0.706,zoneID=17},{npcID=20102,x=0.406,y=0.844,zoneID=67},{npcID=20102,x=0.522,y=0.284,zoneID=440},{npcID=20102,x=0.598,y=0.496,zoneID=618},{npcID=20102,x=0.338,y=0.64,zoneID=3523},{npcID=20102,x=0.53,y=0.504,zoneID=3703},{npcID=20102,x=0.416,y=0.742,zoneID=5287},{npcID=220307,x=0.46,y=0.548,zoneID=14771},{npcID=220870,x=0.554,y=0.61,zoneID=14771},{npcID=220307,x=0.512,y=0.764,zoneID=15969}},ends={{npcID=51665,x=0.32,y=0.504,zoneID=12}},coords={x=0.616,y=0.74,source="quest_giver",zoneID=1519},questType="standard"},
[29075] = {id=29075,name="A Time to Gain",level=10,requiredLevel=10,faction="alliance",expansion=3,zoneID=12,description="Greetings, . The Wickerman you see before you symbolizes self. The flames that burn it are a cleansing fire. Tradition states that we take our burdens and give them to the fires. We let go of our burdens as we approach the winter season and we gain clarity and peace. Join us in our tradition, . Take a branch from the nearby bonfire and hurl it at the Wickerman.",starts={{npcID=51665,x=0.32,y=0.504,zoneID=12}},ends={{npcID=51665,x=0.32,y=0.504,zoneID=12}},coords={x=0.32,y=0.504,source="quest_giver",zoneID=12},questType="standard"},
[29078] = {id=29078,name="Beating Them Back!",level=1,requiredLevel=1,faction="alliance",expansion=3,zoneID=6170,description="Another Alliance recruit, eh? I'm Marshal McBride , commander of this garrison. We don't see many of your kind here, , but we could sure use the help. You've arrived just in time. The Blackrock orcs have managed to sneak into Northshire through a break in the mountain. My soldiers are doing the best that they can to push them back, but I fear they will be overwhelmed soon. Head northwest into the forest and kill the attacking Blackrock worgs ! Help my soldiers!",starts={{npcID=197,x=0.48,y=0.42,zoneID=12},{npcID=197,x=0.332,y=0.532,zoneID=6170}},ends={{npcID=197,x=0.48,y=0.42,zoneID=12},{npcID=197,x=0.332,y=0.532,zoneID=6170}},coords={x=0.48,y=0.42,source="quest_giver",zoneID=12},questType="standard"},
[29079] = {id=29079,name="Lions for Lambs",level=1,requiredLevel=1,faction="alliance",expansion=3,zoneID=6170,description="The invading orcs aren't fools. They are sizing us up, making sure that when they attack it will be to their advantage. In the forest, to the northwest, are Blackrock spies. They peer at us through spyglasses, watching our every move - waiting. I want you take the fight to them! Kill the Blackrock spies! We must show them that we know they are watching us and that we are prepared!",starts={{npcID=197,x=0.48,y=0.42,zoneID=12},{npcID=197,x=0.332,y=0.532,zoneID=6170}},ends={{npcID=197,x=0.48,y=0.42,zoneID=12},{npcID=197,x=0.332,y=0.532,zoneID=6170}},coords={x=0.48,y=0.42,source="quest_giver",zoneID=12},questType="standard"},
[29080] = {id=29080,name="Join the Battle!",level=1,requiredLevel=1,faction="alliance",expansion=3,zoneID=6170,description="I have here an urgent message from Sergeant Willem . Turns out that the Blackrock orcs have hired goblin assassins. They ambushed our battalion behind the abbey. Willem has asked me to send him a hero. You have to go help them, ! Find Sergeant Willem north of the abbey at the command tent. Go!",starts={{npcID=197,x=0.48,y=0.42,zoneID=12},{npcID=197,x=0.332,y=0.532,zoneID=6170}},ends={{npcID=823,x=0.488,y=0.384,zoneID=12},{npcID=823,x=0.356,y=0.4,zoneID=6170}},coords={x=0.48,y=0.42,source="quest_giver",zoneID=12},questType="standard"},
[29081] = {id=29081,name="They Sent Assassins",level=1,requiredLevel=1,faction="alliance",expansion=3,zoneID=6170,description="Have you ever seen a goblin, ? They're wretched little monsters that love only two things: gold and themselves. The Blackrock orcs have enlisted the aid of goblin assassins to kill our soldiers. If you look to the field in the north you can barely make out their silhouettes, sneaking about in the grass. I need you to head out there and kill every goblin that you see. They need to learn that nobody messes with the Alliance!",starts={{npcID=823,x=0.488,y=0.384,zoneID=12},{npcID=823,x=0.356,y=0.4,zoneID=6170}},ends={{npcID=823,x=0.488,y=0.384,zoneID=12},{npcID=823,x=0.356,y=0.4,zoneID=6170}},coords={x=0.488,y=0.384,source="quest_giver",zoneID=12},questType="standard"},
[29082] = {id=29082,name="Fear No Evil",level=1,requiredLevel=1,faction="alliance",expansion=3,zoneID=6170,description="Have you embraced the Holy Light yet, ? It is through the Holy Light that we are saved! It is through the Holy Light that I am able to heal these overly demanding soldiers! And it is through the Holy Light that you will be able to venture out into the field to the north and rescue our fallen brothers! Take this prayer book with you into the field and cast the Light's healing touch on the injured.",starts={{npcID=951,x=0.486,y=0.38,zoneID=12},{npcID=951,x=0.35,y=0.386,zoneID=6170}},ends={{npcID=951,x=0.486,y=0.38,zoneID=12},{npcID=951,x=0.35,y=0.386,zoneID=6170}},coords={x=0.486,y=0.38,source="quest_giver",zoneID=12},questType="standard"},
[29083] = {id=29083,name="The Rear is Clear",level=1,requiredLevel=1,faction="alliance",expansion=3,zoneID=6170,description="Excellent work, ! The rear is now officially clear. We'll take care of the stragglers. I want you to go back to Marshal McBride , standing in front of Northshire Abbey, south of here, and let him know that the goblin situation is under control. Farewell, .",starts={{npcID=823,x=0.488,y=0.384,zoneID=12},{npcID=823,x=0.356,y=0.4,zoneID=6170}},ends={{npcID=197,x=0.48,y=0.42,zoneID=12},{npcID=197,x=0.332,y=0.532,zoneID=6170}},coords={x=0.488,y=0.384,source="quest_giver",zoneID=12},questType="standard"},
[29084] = {id=29084,name="Classic Random 35-39 (1st)",level=1,requiredLevel=1,faction="none",expansion=3,questType="standard"},
[29086] = {id=29086,name="Competition Schmompetition",level=5,requiredLevel=5,faction="horde",expansion=3,zoneID=17,description="I'm just a little guy, trying to set up my own independent business. Working hard toward the Azerothian dream, ya know? Well soon as I set up shop, the Venture Co. next door decided they wanted me out. They've been harrassing me with threatening letters, using words like 'cease' and 'desist.' Worst of all, the schematics for my newest machine are missing, and I know those corporate pilferers stole them! Go to the Sludge Fen and knock out some of their employees. I know they're hiding my blueprints!",starts={{npcID=3442,x=0.622,y=0.174,zoneID=17}},ends={{npcID=3442,x=0.622,y=0.174,zoneID=17}},coords={x=0.622,y=0.174,source="quest_giver",zoneID=17},questType="standard"},
[29087] = {id=29087,name="Sludge Investigation",level=5,requiredLevel=5,faction="horde",expansion=3,zoneID=17,description="Hey , do you see this footprint? We found them all over the camp last night! Nothing's missing, but all our belongings have been...examined. The muddy trails lead back toward the Sludge Fen. Someone's been sniffing around, and I don't like it one bit. Can you go west to the Sludge Fen and investigate? See if you can find any more tracks just like this one!",starts={{npcID=34698,x=0.624,y=0.168,zoneID=17}},ends={{npcID=34698,x=0.624,y=0.168,zoneID=17}},coords={x=0.624,y=0.168,source="quest_giver",zoneID=17},questType="standard"},
[29088] = {id=29088,name="Hyena Extermination",level=5,requiredLevel=5,faction="horde",expansion=3,zoneID=17,description="Hey , we've got a real problem here. There's an overpopulation of hyenas just west of the Sludge Fen, and they're starting to become a menace. If I have to listen to them caterwauling one more night, I just might go crazy! Vernon over there says the hyenas might even have made off with one of his stabled pigs. We can't have that happening. Can you go thin out the hyena numbers? You'll find them parading in broad daylight to the west.",starts={{npcID=34698,x=0.624,y=0.168,zoneID=17}},ends={{npcID=34698,x=0.624,y=0.168,zoneID=17}},coords={x=0.624,y=0.168,source="quest_giver",zoneID=17},questType="standard"},
[29089] = {id=29089,name="Sludge Beast!",level=5,requiredLevel=5,faction="horde",expansion=3,zoneID=17,description="Whatever is lurking around the Sludge Fen, it doesn't appear to be human. Judging from the remains around its tracks, it's also dangerous. You decide to follow the tracks down to the bottom of the lake and look for the creature's resting place.",starts={{npcID=34698,x=0.624,y=0.168,zoneID=17}},ends={{npcID=34698,x=0.624,y=0.168,zoneID=17}},coords={x=0.624,y=0.168,source="quest_giver",zoneID=17},questType="standard"},
[29090] = {id=29090,name="A Burning Threat",level=5,requiredLevel=5,faction="horde",expansion=3,zoneID=17,description="While we cast our eyes toward the cataclysm, who watches our backs? While our leaders take up arms against Deathwing, the Burning Blade plots our downfall. Even as we speak, they are gathering recruits and supplies at the farm to the southwest. I care not to meet death at the hands of the Burning Legion. It's time we take matters into our own hands. , will you help me keep the vigil? Go and slaughter their ranks before it's too late.",starts={{npcID=52192,x=0.442,y=0.25,zoneID=17}},ends={{npcID=52192,x=0.442,y=0.25,zoneID=17}},coords={x=0.442,y=0.25,source="quest_giver",zoneID=17},questType="standard"},
[29092] = {id=29092,name="Inform the Elder",level=1,requiredLevel=1,faction="alliance",expansion=3,zoneID=3703,description="This information must be spread to the entirety of the Earthen Ring. I'm not certain how to proceed, but the elder who set you on this task in the first place may. Please, return to the elder and seek the next course of action - we must do something!",starts={{npcID=25324,x=0.146,y=0.226,zoneID=331}},ends={{npcID=26221,x=0.62,y=0.678,zoneID=85},{npcID=26221,x=0.67,y=0.13,zoneID=1497},{npcID=26221,x=0.494,y=0.72,zoneID=1519},{npcID=26221,x=0.648,y=0.274,zoneID=1537},{npcID=26221,x=0.472,y=0.376,zoneID=1637},{npcID=26221,x=0.212,y=0.244,zoneID=1638},{npcID=26221,x=0.622,y=0.492,zoneID=1657},{npcID=26221,x=0.688,y=0.426,zoneID=3487},{npcID=26221,x=0.432,y=0.258,zoneID=3557},{npcID=26221,x=0.604,y=0.308,zoneID=3703}},coords={x=0.146,y=0.226,source="quest_giver",zoneID=331},questType="standard"},
[29094] = {id=29094,name="The Short Way Home",level=5,requiredLevel=5,faction="horde",expansion=3,zoneID=17,description="Looks like your work here is done, . You'd better head back to the Crossroads. Luckily for you, my Silver Bullet X-831 prototype is finished, and she's ready for a test drive. Whaddaya say you do me one last favor and take her for a little spin? One of my assistants will accompany you. Your sweet, sweet ride is waiting on the platform behind me. Just hop on when you're ready.",starts={{npcID=3442,x=0.622,y=0.174,zoneID=17}},ends={{npcID=3449,x=0.306,y=0.458,zoneID=17}},coords={x=0.622,y=0.174,source="quest_giver",zoneID=17},questType="standard"},
[29095] = {id=29095,name="Report to Thork",level=5,requiredLevel=5,faction="horde",expansion=3,zoneID=17,description="Now that the threat here has been stilled, you should return to the Crossroads. Thork would like to speak to you. Farewell, friend.",starts={{npcID=3449,x=0.306,y=0.458,zoneID=17}},ends={{npcID=3429,x=0.486,y=0.596,zoneID=17}},coords={x=0.306,y=0.458,source="quest_giver",zoneID=17},questType="standard"},
[29100] = {id=29100,name="Bwemba's Spirit",level=35,requiredLevel=35,faction="alliance",expansion=3,zoneID=1519,description="Dese be troublin' times for us Darkspear. Da Zandalar be reuniting all da troll clans an' plan to take back da lands dey lost. We tryin' to warn all dat we can. But it might be too late. Another Darkspear gone down to Stranglethorn to warn da people. But it ain't safe to travel alone in Stranglethorn. Help me find him and make sure da people in Stranglethorn are warned of da rise of da troll tribes. I gonna bind my spirit wit' ya. When ya get to Stranglethorn, I be able to aid ya.",starts={{npcID=52654,x=0.26,y=0.292,zoneID=1519}},coords={x=0.26,y=0.292,source="quest_giver",zoneID=1519},questType="standard"},
[29101] = {id=29101,name="Punting Season",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=616,description="Baby turtles are sweet, even if they can be somewhat bitey. Mylune holds up a bandaged finger.> But they're so slow with their tiny little legs, they can't escape the fire creatures who are attacking Hyjal! Mylune claps her hands together.> PLEASE save them, ! Pick up the wee turtles and punt them into the water of the Ashen Lake. Don't worry about the kicking, they have hard shells. They also have hard teeth, so don't pick them up by the mouth.",starts={{npcID=52671,x=0.272,y=0.62,zoneID=616}},ends={{npcID=52671,x=0.272,y=0.62,zoneID=616}},coords={x=0.272,y=0.62,source="quest_giver",zoneID=616},questType="standard"},
[29102] = {id=29102,name="To Fort Livingston",level=35,requiredLevel=35,faction="alliance",expansion=3,zoneID=33,description="Da first place we check gonna be da place most likely to be attacked first. You call it Fort Livingston. Fort Livingston be surrounded by troll ruins... It make for an easy target. Maybe we find da emissary dere. Hopefully it ain't too late.",starts={{npcID=52654,x=0.26,y=0.292,zoneID=1519}},ends={{npcID=52281,x=0.528,y=0.672,zoneID=33}},coords={x=0.26,y=0.292,source="quest_giver",zoneID=1519},questType="standard"},
[29103] = {id=29103,name="Serpents and Poison",level=35,requiredLevel=35,faction="alliance",expansion=3,zoneID=33,description="Because of the emissary's warning we were able to gather more adventurers to help defend. But we thought we were going to be fighting trolls. Instead we found ourselves overwhelmed by serpents! They seem to have come from everywhere. We are barely able to hold on, and I only suspect it's going to get worse. Help us and eliminate the serpents and perhaps your troll friend here can use some magic to cure the poisoned.",starts={{npcID=52281,x=0.528,y=0.672,zoneID=33}},ends={{npcID=52281,x=0.528,y=0.672,zoneID=33}},coords={x=0.528,y=0.672,source="quest_giver",zoneID=33},questType="standard"},
[29104] = {id=29104,name="Spirits Are With Us",level=35,requiredLevel=35,faction="alliance",expansion=3,zoneID=33,description="Dere was somethin' not right about dem serpents, . Dere was a trace of some bad mojo in da poison an' dat don't happen naturally. Da bonfire in da middle of da camp, we can use dat to perform a ritual. Whatever be makin' dese serpents attack, dey probably still watchin' over dem. Da only problem, , is dat I only be here in spirit form. I need you to be my hands. I need you to go to da fire an' prepare it for me. Den I'll handle da rest.",questType="standard"},
[29105] = {id=29105,name="Nesingwary Will Know",level=35,requiredLevel=35,faction="alliance",expansion=3,zoneID=33,description="Great, just what we need, the Gurubashi on the rampage using serpents to lead the charge. Well at least we know that much. It's probably a safe bet that the hunters at Nesingwary's Expedition have some insight into this. If they don't they at least know how to fight the serpents. Head there and let them know what you saw here. Let them know that the trolls are using serpents as their weapon.",starts={{npcID=52281,x=0.528,y=0.672,zoneID=33}},ends={{npcID=52294,x=0.44,y=0.23,zoneID=33}},coords={x=0.528,y=0.672,source="quest_giver",zoneID=33},questType="standard"},
[29109] = {id=29109,name="Mor'shan Caravan Pick-Up",level=5,requiredLevel=5,faction="horde",expansion=3,zoneID=17,description="The battle in Ashenvale rages on without relent. Our forces at the Mor'shan Ramparts are in desperate need of reinforcements and supplies. We have a major shipment of medicines and food headed north, and I need a capable like you to guard it. Rocco Whipshank waits for you at the road north out of the Crossroads. Let him know you are ready to accompany the caravan.",starts={{npcID=3429,x=0.486,y=0.596,zoneID=17}},ends={{npcID=52207,x=0.476,y=0.396,zoneID=17}},coords={x=0.486,y=0.596,source="quest_giver",zoneID=17},questType="standard"},
[29110] = {id=29110,name="Mor'shan Caravan Rescue",level=5,requiredLevel=5,faction="horde",expansion=3,zoneID=17,description="They took Balgor and the caravan supplies from our very doorstep! Those supplies are vital for our victory against the Alliance in Ashenvale, and Balgor...if anything happens to my dear little brother, I will rip every Burning Blade member to shreds myself. , I need you to rescue Balgor and the captured caravan. Follow the path just north of us, up onto Dreadmist Peak. Do not let any of those Burning Blade dogs live.",starts={{npcID=52207,x=0.476,y=0.396,zoneID=17}},ends={{npcID=52309,x=0.41,y=0.392,zoneID=17}},coords={x=0.476,y=0.396,source="quest_giver",zoneID=17},questType="standard"},
[29111] = {id=29111,name="Mor'shan Caravan Delivery",level=5,requiredLevel=5,faction="horde",expansion=3,zoneID=17,description="You've managed to stir the Burning Blade's nest. Our scouts report that they are gathering for an attack. You must complete the caravan's journey before they arrive. The supplies are packed, the kodos are rested, and I hope you don't mind but I made a few adjustments to your gun. If you meet up with any resistance, shoot first and ask questions later. Quickly! They come! Speak to me when you are ready to leave.",starts={{npcID=52207,x=0.476,y=0.396,zoneID=17}},ends={{npcID=8582,x=0.426,y=0.15,zoneID=17}},coords={x=0.476,y=0.396,source="quest_giver",zoneID=17},questType="standard"},
[29112] = {id=29112,name="Demon Seed",level=5,requiredLevel=5,faction="horde",expansion=3,zoneID=17,description="Listen , we can't leave quite yet. I managed to overhear their plans while they were preparing for the ritual sacrifice. They're planning to use a powerful artifact called the Demon Seed to launch a full scale attack on the Horde. They're keeping it under close guard over in that cave. If you can get your hands on the Demon Seed , we should take it to my sister Nagala. She'll know what to do with it.",starts={{npcID=52309,x=0.41,y=0.392,zoneID=17}},ends={{npcID=52207,x=0.476,y=0.396,zoneID=17}},coords={x=0.41,y=0.392,source="quest_giver",zoneID=17},questType="standard"},
[29114] = {id=29114,name="Track the Tracker",level=35,requiredLevel=35,faction="alliance",expansion=3,zoneID=33,description="We've been fending off serpents for days now, . But the serpents are nothing compared to what else is out in that jungle. We hunters are being hunted. A large panther named Mauti has been dragging my men off into the bush. We sent Grent Direhammer , one of our best hunters, to track this beast down. Direhammer headed off to the east, perhaps you can find them there.",starts={{npcID=52294,x=0.44,y=0.23,zoneID=33}},ends={{npcID=52346,x=0.502,y=0.216,zoneID=33}},coords={x=0.44,y=0.23,source="quest_giver",zoneID=33},questType="standard"},
[29115] = {id=29115,name="The Hunter's Revenge",level=35,requiredLevel=35,faction="alliance",expansion=3,zoneID=33,description="The beast that's been hunting us... I've been hunting it. We call him Mauti. He's a clever one. But he made a grave mistake when he killed my brother. Now that mistake is going to cost him. Ol' Direhammer has got his scent. I've noticed him roaming just above Kurzen's Compound. If we act fast, we can take him down. Are you ready, ?",starts={{npcID=52346,x=0.502,y=0.216,zoneID=33}},coords={x=0.502,y=0.216,source="quest_giver",zoneID=33},questType="standard"},
[29118] = {id=29118,name="Follow That Cat",level=35,requiredLevel=35,faction="alliance",expansion=3,zoneID=33,description="The real Mauti has run off with Grent Direhammer, but being the wise hunter that he is, he has fired flares off so you can track him. Find Direhammer before it's too late!",starts={{npcID=208365,x=0.646,y=0.22,zoneID=33}},coords={x=0.646,y=0.22,source="quest_giver",zoneID=33},questType="standard"},
[29120] = {id=29120,name="Mauti",level=35,requiredLevel=35,faction="alliance",expansion=3,zoneID=33,description="I got da feeling dat somethin' ain't right wit' dat panther, . It ain't natural. I gonna need to perform some rituals over da body. Put Mauti down, an' den let's see what we can find out, .",questType="standard"},
[29121] = {id=29121,name="Bury Me With Me Boots...",level=35,requiredLevel=35,faction="alliance",expansion=3,zoneID=33,description="Ah... It's you, . Mauti... He's dead? Then my brother has been avenged. I've only one request from ya... This scamp here, he's been pawing at me bare feet. No dwarf should go to the earth with bare feet. Please, bury me with me boots.",starts={{npcID=52371,x=0.76,y=0.666,zoneID=33}},ends={{npcID=52371,x=0.76,y=0.666,zoneID=33}},coords={x=0.76,y=0.666,source="quest_giver",zoneID=33},questType="standard"},
[29122] = {id=29122,name="Echoes of Nemesis",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=616,description="Mylune 's voice sings like a melody in your head.> Remember that awful fire turtle, Nemesis , from the Firelands? He's dead now (yay!) but echoes of him keep trying to break through to Mount Hyjal. Go to the shores of the Ashen Lake and speak with my friend Tooga. Let him know you're ready to fight an echo of Nemesis , and the turtles will draw him into this world. Then you can hit him! Hard! Hide inside of Tooga's shell if he starts to erupt.",starts={{npcID=52671,x=0.272,y=0.62,zoneID=616}},ends={{npcID=52671,x=0.272,y=0.62,zoneID=616}},coords={x=0.272,y=0.62,source="quest_giver",zoneID=616},questType="standard"},
[29124] = {id=29124,name="Warn the Rebel Camp",level=35,requiredLevel=35,faction="alliance",expansion=3,zoneID=33,description="Dis death ain't be in vain, . We figure out dat Kilnara be on da prowl. Tings don't look good. We better check out da Rebel Camp to da north. Maybe we find my contact dere.",ends={{npcID=52410,x=0.476,y=0.12,zoneID=33}},questType="standard"},
[29125] = {id=29125,name="Between the Trees",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=616,description="Spirit fragments of Malorne - seen to us mortals as ghostly white deer - still frolic through these forests. While Malorne is no longer with us, these pieces of his spirit may be of use to us. Travel east and walk among the trees. If you are able to get close enough to one of the spirit fragments, it will bestow its power to you. Oh, and take this staff. You may need it later.",starts={{npcID=52669,x=0.272,y=0.624,zoneID=616}},ends={{npcID=52669,x=0.272,y=0.624,zoneID=616}},coords={x=0.272,y=0.624,source="quest_giver",zoneID=616},questType="standard"},
[29126] = {id=29126,name="The Power of Malorne",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=616,description="Matoclaw 's voice continues.> The portal that opened up to our east is guarded by a powerful flamewaker by the name of Galenges . We will need all of Malorne's help in defeating him. Do you remember the staff that I gave you? Place it in the pile of ash in front of the portal. Then pray that Malorne comes to your aid.",starts={{npcID=52669,x=0.272,y=0.624,zoneID=616}},ends={{npcID=52669,x=0.272,y=0.624,zoneID=616}},coords={x=0.272,y=0.624,source="quest_giver",zoneID=616},questType="standard"},
[29128] = {id=29128,name="The Protectors of Hyjal",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="We need to place pressure on the assault camp at Sethria's Roost. Ragnaros' minions are using this area as a point to push their battlefront beyond the bounds of Hyjal. I'm putting you in charge of a small squad to deal with them. I have selected an elite group of fighters to assist you. Travel to Sethria's Roost. Your compatriots have been instructed to meet you once you arrive. Then put an end to the elementals' assault.",starts={{npcID=53073,x=0.274,y=0.616,zoneID=616}},ends={{npcID=52824,x=0.458,y=0.858,zoneID=5733}},coords={x=0.274,y=0.616,source="quest_giver",zoneID=616},questType="standard"},
[29129] = {id=29129,name="A Legendary Engagement",level=35,requiredLevel=35,faction="horde",expansion=3,zoneID=440,description="A pleasure, . Ziradormi smiles.> It was kind of you to arrive so quickly. For reasons unknown to me, my master seeks audience with you. I would counsel you not to take this invitation lightly. Anachronos seldom has cause to interact with mortals. Wisdom would dictate that you seek him out in the Caverns of Time at once. Speak to me when you are ready and I shall personally deliver you.",starts={{npcID=52382,x=0.488,y=0.704,zoneID=1637}},coords={x=0.488,y=0.704,source="quest_giver",zoneID=1637},questType="standard"},
[29131] = {id=29131,name="Defend the Rebel Camp",level=35,requiredLevel=35,faction="alliance",expansion=3,zoneID=33,description="We are in trouble here, . Your troll friend has been through here and warned us that things were going to get serious, but I didn't think it would be this bad. We are doing our best to hold off these trolls. But any help you can offer would greatly help.",starts={{npcID=52410,x=0.476,y=0.12,zoneID=33}},ends={{npcID=52410,x=0.476,y=0.12,zoneID=33}},coords={x=0.476,y=0.12,source="quest_giver",zoneID=33},questType="standard"},
[29132] = {id=29132,name="A Legendary Engagement",level=35,requiredLevel=35,faction="alliance",expansion=3,zoneID=440,description="I expected that I would find you here, . But then, we of the bronze flight have somewhat of an advantage when it comes to such things. Coridormi smiles.> For reasons unknown to me, my master seeks audience with you. I would counsel you not to take this invitation lightly, . Anachronos seldom has cause to interact with mortals. Wisdom would dictate that you seek him out in the Caverns of Time at once. Speak to me when you are ready and I shall personally deliver you.",starts={{npcID=52408,x=0.494,y=0.874,zoneID=1519}},coords={x=0.494,y=0.874,source="quest_giver",zoneID=1519},questType="standard"},
[29133] = {id=29133,name="To the Digsite",level=35,requiredLevel=35,faction="alliance",expansion=3,zoneID=33,description="The other Darkspear emissary was here briefly. He was eager to get to the next location and warn them. I sent him on a flight to the Explorers' League Digsite in the Cape of Stranglethorn. I hope he wasn't too late. I will give you use of one of my gryphons, a direct flight there. Talk to me when you are ready to go, .",starts={{npcID=52753,x=0.478,y=0.118,zoneID=33}},coords={x=0.478,y=0.118,source="quest_giver",zoneID=33},questType="standard"},
[29134] = {id=29134,name="A Wrinkle in Time",level=35,requiredLevel=35,faction="both",expansion=3,zoneID=440,description="Listen carefully, , for though we are only beginning, time already grows short and the consequences of our failure are unfathomable. An event in the recent past has been obscured from my vision by the most powerful of magics. Its impact, however, has not. If action is not taken to change the course of this timeline's future, the outcome is clear. Brace yourself, mortal, and behold the future of Azeroth.",questType="standard"},
[29135] = {id=29135,name="All-Seeing Eye",level=35,requiredLevel=35,faction="both",expansion=3,zoneID=440,description="I perceive the questions that burn within your mind and I must confess that I share in your uncertainty... a rare position for one such as I, and a most unsettling one. As I scour time to find traces of this obscured event, you must aid me in the creation of an Eye, both to test your worthiness, and to provide an essential tool in the unraveling of this mystery. Venture into the Plane of Fire, , and gather Eternal Embers . Bring them to me with Sands of Time and I will create the Eye.",questType="raid"},
[29137] = {id=29137,name="Breach in the Defenses",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5723,description="Lava worms are bursting through the ground behind our lines, breaking our formations and allowing elementals to slip through. You'll find them scattered throughout our entire front to the north, and upon the Ashen Fields further out. Stomp them back into their holes.",starts={{npcID=52824,x=0.458,y=0.858,zoneID=5733}},ends={{npcID=52824,x=0.458,y=0.858,zoneID=5733}},coords={x=0.458,y=0.858,source="quest_giver",zoneID=5733},questType="standard"},
[29138] = {id=29138,name="Burn Victims",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="We have warriors out in the field who are falling wounded, and many of our druids are too busy fighting to give them proper aid. I need you to go to the north, towards the Ashen Fields, and tend their wounds at least enough that they can make it back to safety. If you haven't any bandages or healing spells, I had Rayne put together this salve, which should prove sufficient to get them on their feet.",starts={{npcID=53080,x=0.458,y=0.858,zoneID=5733}},ends={{npcID=53080,x=0.458,y=0.858,zoneID=5733}},coords={x=0.458,y=0.858,source="quest_giver",zoneID=5733},questType="standard"},
[29139] = {id=29139,name="Aggressive Growth",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="Our warriors are doing everything they can to hold back the elementals, but their numbers are endless. We need to do something to slow down the assault. Find some suitable patches of dirt or ash out on the Ashen Fields to our north and plant these seeds. They will grow deadly vines that may slow down our enemies a bit. It's not much, but every bit helps.",starts={{npcID=52467,x=0.486,y=0.86,zoneID=5733}},ends={{npcID=52467,x=0.486,y=0.86,zoneID=5733}},coords={x=0.486,y=0.86,source="quest_giver",zoneID=5733},questType="standard"},
[29141] = {id=29141,name="The Harder They Fall",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="Molten Behemoths have joined the elementals upon the battlefield. They are crushing our front lines. I need you to halt their momentum. You'll find the beasts slow and clumsy. They can easily be outmaneuvered, but they will pack a devastating punch if they hit you. Be nimble, .",starts={{npcID=52824,x=0.458,y=0.858,zoneID=5733}},ends={{npcID=52824,x=0.458,y=0.858,zoneID=5733}},coords={x=0.458,y=0.858,source="quest_giver",zoneID=5733},questType="standard"},
[29142] = {id=29142,name="Traitors Return",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="The Druids of the Flame assault our front line, . These vile creatures have turned their backs on Elune's teachings and worship instead the Fire Lord, Ragnaros. Twisted by his insane power, they desire nothing more than to bury us in ash. We must counter their attack immediately!",starts={{npcID=52824,x=0.458,y=0.858,zoneID=5733}},ends={{npcID=52824,x=0.458,y=0.858,zoneID=5733}},coords={x=0.458,y=0.858,source="quest_giver",zoneID=5733},questType="standard"},
[29143] = {id=29143,name="Wisp Away",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="The fire elementals are pouring out of portals on the far side of the Ashen Fields. We need someone to close them. Cut off some of their reinforcements. Banishing these kinds of elemental magics is something our wisps are perfectly suited for. One will come with you. Lead it to a portal and keep it alive until it finishes.",starts={{npcID=52467,x=0.486,y=0.86,zoneID=5733}},ends={{npcID=52467,x=0.486,y=0.86,zoneID=5733}},coords={x=0.486,y=0.86,source="quest_giver",zoneID=5733},questType="standard"},
[29144] = {id=29144,name="Clean Up in Stormwind",level=10,requiredLevel=10,faction="alliance",expansion=3,zoneID=12,description="Greetings, ! Are you enjoying Hallow's End? It seems that in response to our stink bombing the Undercity, the Horde has decided to stink bomb our city. The stink bombs they drop are more potent than the ones used in the past. The power of pine won't be enough. We will need something with a little more power. Use this Arcane Cleanser to remove the stink bombs from the city.",starts={{npcID=51934,x=0.322,y=0.508,zoneID=12}},ends={{npcID=51934,x=0.322,y=0.508,zoneID=12}},coords={x=0.322,y=0.508,source="quest_giver",zoneID=12},questType="standard"},
[29145] = {id=29145,name="Opening the Door",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=616,description="You're a bit late. Hamuul, Malfurion, and some of our esteemed guests have already traveled to the invasion point, atop that cliff. Our gate to the Firelands is not yet completed, but it will be shortly. The sooner we can break through, the better. Go on! Hamuul will be expecting you.",starts={{npcID=52669,x=0.272,y=0.624,zoneID=616}},ends={{npcID=52838,x=0.27,y=0.546,zoneID=616}},coords={x=0.272,y=0.624,source="quest_giver",zoneID=616},questType="standard"},
[29147] = {id=29147,name="Call the Flock",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=616,description="Today, we have an opportunity to make another assault against one of Ragnaros' greater minions: Millagazor. However, we first need to get some assistance. Matoclaw holds up a large, silky feather.> Use this artifact to invoke the power of Aviana. Once you have done so, travel northwest and gather some of her flock by calling out to them. Once you have done so, we may proceed against Millagazor.",starts={{npcID=52669,x=0.272,y=0.624,zoneID=616}},ends={{npcID=52669,x=0.272,y=0.624,zoneID=616}},coords={x=0.272,y=0.624,source="quest_giver",zoneID=616},questType="standard"},
[29148] = {id=29148,name="Wings Aflame",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=616,description="Matoclaw 's voice continues to echo within your head.> Millagazor is a creature of flame, but in many ways, he is not unlike the birds of this land. As such, Aviana's artifacts may still have the power to summon him. The fiery portal to the west is where you will find him. Use the quill near the portal's entrance, then prepare for a fierce battle.",starts={{npcID=52669,x=0.272,y=0.624,zoneID=616}},ends={{npcID=52669,x=0.272,y=0.624,zoneID=616}},coords={x=0.272,y=0.624,source="quest_giver",zoneID=616},questType="standard"},
[29150] = {id=29150,name="Voodoo Zombies",level=35,requiredLevel=35,faction="alliance",expansion=3,zoneID=33,description="Da people... Dey all zombies, voodoo zombies! Dis ain't gonna be pretty, . You gotta kill dem. But once dey killed, dere is a moment where I can save dem. Change dem back into da person dey were before. We gotta act fast. Da zombies don' rest.",questType="standard"},
[29151] = {id=29151,name="Bad Supplies",level=35,requiredLevel=35,faction="alliance",expansion=3,zoneID=33,description="Some of da survivors mentioned food, . We better check da food supplies. I gotta a bad feelin' about dis.",questType="standard"},
[29152] = {id=29152,name="Making Contact",level=35,requiredLevel=35,faction="alliance",expansion=3,zoneID=5287,description="You aren't one of the zombies... A troll? I did see one, just before the outbreak... He warned us, told us to be on our guard... But it was too late. Your troll friend headed to Booty Bay to warn them...",starts={{npcID=52646,x=0.552,y=0.42,zoneID=5287}},ends={{npcID=52767,x=0.41,y=0.732,zoneID=5287}},coords={x=0.552,y=0.42,source="quest_giver",zoneID=5287},questType="standard"},
[29153] = {id=29153,name="Booty Bay's Interests",level=35,requiredLevel=35,faction="alliance",expansion=3,zoneID=1977,description="Look, . You've helped out plenty so far, but that's not going to be enough. I need these crazy trolls stopped, or at least stopped from getting into Booty Bay. I'm going to send a man in to oversee the action, but I want you to go into Zul'Gurub and make something happen. At the very least, I want you to find me something that will help keep these trolls out of Booty Bay. You do that and we'll treat you right.",starts={{npcID=2496,x=0.41,y=0.73,zoneID=5287}},ends={{npcID=2496,x=0.41,y=0.73,zoneID=5287},{npcID=53151,x=0.306,y=0.476,zoneID=1977}},coords={x=0.41,y=0.73,source="quest_giver",zoneID=5287},questType="dungeon"},
[29154] = {id=29154,name="Booty Bay's Interests",level=35,requiredLevel=35,faction="alliance",expansion=3,zoneID=5287,description="I've been sent here by Baron Revilgaz of Booty Bay to make sure this troll menace is halted. Or that it is at least halted at the gates of Booty Bay. I want action and I want results. I want you to get in there and kill. I want you to get in there and find me something that will help keep these trolls out of Booty Bay. You do that and we'll make sure you get paid.",starts={{npcID=53151,x=0.306,y=0.476,zoneID=1977}},ends={{npcID=53151,x=0.306,y=0.476,zoneID=1977},{npcID=2496,x=0.41,y=0.73,zoneID=5287}},coords={x=0.306,y=0.476,source="quest_giver",zoneID=1977},questType="dungeon"},
[29155] = {id=29155,name="A Shiny Reward",level=35,requiredLevel=35,faction="alliance",expansion=3,zoneID=1977,description="There is a stash of loot located in the statue on Janeiro's Point just northwest of Booty Bay in Stranglethorn Vale. Head to the statue and claim your prize, .",starts={{npcID=2496,x=0.41,y=0.73,zoneID=5287},{npcID=53151,x=0.306,y=0.476,zoneID=1977}},ends={{npcID=208420,x=0.355,y=0.636,zoneID=5287}},coords={x=0.41,y=0.73,source="quest_giver",zoneID=5287},questType="standard"},
[29156] = {id=29156,name="The Troll Incursion",level=35,requiredLevel=35,faction="alliance",expansion=3,zoneID=3557,description="A group of trolls, claiming to represent the Darkspear tribe, have arrived at Stormwind Harbor. Our guards are keeping them at bay, for now. The Stormwind Harbor Guards are seeking seasoned adventurers for help in removing the trolls from the harbor. Report to Commander Sharp at Stormwind Harbor.",starts={{npcID=206111,x=0.629,y=0.717,zoneID=1519},{npcID=206294,x=0.623,y=0.301,zoneID=1519},{npcID=207320,x=0.258,y=0.696,zoneID=1537},{npcID=207320,x=0.414,y=0.448,zoneID=7078},{npcID=207321,x=0.45,y=0.499,zoneID=1657},{npcID=207322,x=0.552,y=0.474,zoneID=3557}},ends={{npcID=53352,x=0.264,y=0.294,zoneID=1519}},coords={x=0.629,y=0.717,source="quest_giver",zoneID=1519},questType="standard"},
[29159] = {id=29159,name="Pyrorachnophobia",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="We've fought hard to secure this area, but our foothold is tenuous. Our scouts report that the area around us is teeming with vicious fire spiders. They are the spawn of the vicious brood widow, Beth'tilac. Help us hold our line by clearing the area of Cinderweb Spinners or Cinderweb Creepers . It will drive her mad to see her children slain.",starts={{npcID=52921,x=0.66,y=0.64,zoneID=5733}},ends={{npcID=52476,x=0.506,y=0.87,zoneID=5733},{npcID=52921,x=0.66,y=0.64,zoneID=5733}},coords={x=0.66,y=0.64,source="quest_giver",zoneID=5733},questType="standard"},
[29160] = {id=29160,name="Egg-stinction",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="We have a real problem on our hands. Not only are the nearby spiders vicious and predatory, their numbers appear to be endless. We need to stop the growth of their army. Cut their heads off in the egg, not on the battlefield. The Cinderweb Spinners' eggs are laid among the stone pillars to the north. Collect 20 eggs and bring them back to me.",starts={{npcID=52921,x=0.66,y=0.64,zoneID=5733}},ends={{npcID=52476,x=0.506,y=0.87,zoneID=5733},{npcID=52921,x=0.66,y=0.64,zoneID=5733}},coords={x=0.66,y=0.64,source="quest_giver",zoneID=5733},questType="standard"},
[29161] = {id=29161,name="Those Bears Up There",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=616,description="Oh, raspberries! Just when we had saved the last bear cub from the treetops, the fires returned and scared them again! I don't know if you know this, but baby bears are precious and soft. Go to the Whistling Grove, far to the northwest. Climb the trees, grab the bear cubs, and chuck them - gently! - to the soft target in the center of the grove. Mylune suddenly smashes you against her bosom and begins sobbing.> Lil' b-b-b-baby bears! Save them, !",starts={{npcID=52671,x=0.272,y=0.62,zoneID=616}},ends={{npcID=52671,x=0.272,y=0.62,zoneID=616}},coords={x=0.272,y=0.62,source="quest_giver",zoneID=616},questType="standard"},
[29162] = {id=29162,name="Nature's Blessing",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=616,description="Mylune 's voice rings in your head, like the sound of birds chirping.> I love all creatures of the forest, even spiders, despite the fact that they are icky. But the spiders from the Firelands are worse than icky. They're burny, and don't belong here. Find the fire portal in the western Regrowth, and use the gem I gave you earlier to force it open. When a fire spider emerges, step on it! Unless it's big. Then, do something y to it. Oh, and use the gem if spider venom makes you woozy!",starts={{npcID=52671,x=0.272,y=0.62,zoneID=616}},ends={{npcID=52671,x=0.272,y=0.62,zoneID=616}},coords={x=0.272,y=0.62,source="quest_giver",zoneID=616},questType="standard"},
[29164] = {id=29164,name="Perfecting Your Howl",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=616,description="The wolf ancient, Lo'gosh - or, if you prefer, Goldrinn - has many weapons available to him, but always the most underestimated is his howl. Today, we will use this weapon to summon and defeat Lylagar, one of the lieutenants of flame that lurk within the Firelands. Defeat any of the creatures of flame within the Regrowth, and then use the Fang of the Wolf while standing atop their corpse. Soon, your howl will echo across all of Kalimdor.",starts={{npcID=52669,x=0.272,y=0.624,zoneID=616}},ends={{npcID=52669,x=0.272,y=0.624,zoneID=616}},coords={x=0.272,y=0.624,source="quest_giver",zoneID=616},questType="standard"},
[29165] = {id=29165,name="The Call of the Pack",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=616,description="Matoclaw continues:> The easternmost portal of flame is the domain of Lylagar . Stand before the portal, deliver a challenging howl, and then force the fiery beast to submit.",starts={{npcID=52669,x=0.272,y=0.624,zoneID=616}},ends={{npcID=52669,x=0.272,y=0.624,zoneID=616}},coords={x=0.272,y=0.624,source="quest_giver",zoneID=616},questType="standard"},
[29166] = {id=29166,name="Supplies for the Other Side",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=616,description="One of the biggest dangers that our druids face when fighting within the Firelands is simple dehydration. Our proveditors spend a significant amount of time preparing canteens for the troops on the other side. We do have other methods, however. In the greener thickets to the east, you should still find some blueroot vines which have not yet burned. These plants hold a tremendous amount of water in their roots - and also provide some energy for the weary soldier.",starts={{npcID=52669,x=0.272,y=0.624,zoneID=616}},ends={{npcID=52669,x=0.272,y=0.624,zoneID=616}},coords={x=0.272,y=0.624,source="quest_giver",zoneID=616},questType="standard"},
[29172] = {id=29172,name="The Beasts Within",level=35,requiredLevel=35,faction="both",expansion=3,zoneID=1977,description="Bloodslayer T'ara eyes you for a moment.> After de fall of Hakkar, de city of de Gurubashi fell into disrepair, and de jungle claimed most of Zul'Gurub for its own. Some powerful beasts now be livin' in da cracks an' hollows of de ancient city. We seen de powers dem Gurubashi priests wield - dey turn de very plantlife against us wit' venomous concoctions. You tink you be strong? Dispose of dese beasts, before dey become mindless agents of Jin'do.",starts={{npcID=53023,x=0.308,y=0.472,zoneID=1977}},ends={{npcID=53023,x=0.308,y=0.472,zoneID=1977}},coords={x=0.308,y=0.472,source="quest_giver",zoneID=1977},questType="dungeon"},
[29173] = {id=29173,name="Secondary Targets",level=35,requiredLevel=35,faction="both",expansion=3,zoneID=1977,description="Da Gurubashi trolls gathered dere most powerful allies ta rebuild Zul'Gurub an' re-take Stranglethorn Vale. Chief among dem be two monstrous trolls: Kaulema da Mover an' Mor'Lek da Dismantler, an' a powerful soul-stealer called Mortaxx . Dey don't be leaders of da Gurubashi, but killing dem powerful minions gonna help us prevent da rise of da Gurubashi.",starts={{npcID=53023,x=0.308,y=0.472,zoneID=1977}},ends={{npcID=53023,x=0.308,y=0.472,zoneID=1977}},coords={x=0.308,y=0.472,source="quest_giver",zoneID=1977},questType="dungeon"},
[29175] = {id=29175,name="Break Their Spirits",level=35,requiredLevel=35,faction="both",expansion=3,zoneID=1977,description="A city like Zul'Gurub be similar ta one of de many towering trees you see nearby. De trunk may be thick, and de canopy vast and leafy, but without nutrients from de roots far below, de tree gonna wither and fall. Jin'do's army be fed largely by de actions of a couple a' minor Gurubashi trolls. Sever dem roots, and de city gonna fall.",starts={{npcID=53023,x=0.308,y=0.472,zoneID=1977}},ends={{npcID=53023,x=0.308,y=0.472,zoneID=1977}},coords={x=0.308,y=0.472,source="quest_giver",zoneID=1977},questType="dungeon"},
[29177] = {id=29177,name="Vigilance on Wings",level=30,requiredLevel=30,faction="both",expansion=3,zoneID=616,description="The agents of Twilight continue their assault within this pocket of the Firelands. We must not let our offensive fall! Take wing, and destroy as many of those lancers as you can! Do not forget to pick up and equip your lance first.",starts={{npcID=40578,x=0.372,y=0.562,zoneID=616}},ends={{npcID=40578,x=0.372,y=0.562,zoneID=616}},coords={x=0.372,y=0.562,source="quest_giver",zoneID=616},questType="standard"},
[29179] = {id=29179,name="Hostile Elements",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="The elementals continue to press on us, and I do not expect them to subside any time soon. You'll find them pouring across the Ashen Fields to the north. Thin their ranks.",starts={{npcID=52824,x=0.458,y=0.858,zoneID=5733}},ends={{npcID=52824,x=0.458,y=0.858,zoneID=5733}},coords={x=0.458,y=0.858,source="quest_giver",zoneID=5733},questType="standard"},
[29180] = {id=29180,name="Promises, Promises...",level=5,requiredLevel=5,faction="both",expansion=3,zoneID=3805,mapID=2437,description="My inscrutable theories confirm rumors of vast treasure in Zul'Aman . There'll be mounts and mansions for everyone! First things first, though. You must earn your share, after all.... Our initial efforts here haven't gone as well as I hoped. In fact, my map, and the recruits I lent it to, have gone missing. They were after a troll-beast named Nalorakk. Forget the crew, I need that map! Succeed, and you'll go down in history as the one who helped Budd Nedreck unlock the secrets of Zul'Aman !",questType="dungeon"},
[29181] = {id=29181,name="Druids of the Talon",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=616,description="Skylord Omnuron and his Druids of the Talon have been a fearsome force for us back in Hyjal. I know that they prefer the familiar skies of that battlefield, but the time may come when we need them here nonetheless. If you get your hands on enough marks, you should appeal to Omnuron that his druids should be on the main front. Omnuron watches out for his own, but he also understands the importance of this effort.",starts={{npcID=52135,x=0.47,y=0.91,zoneID=5733}},ends={{npcID=50082,x=0.434,y=0.458,zoneID=616}},coords={x=0.47,y=0.91,source="quest_giver",zoneID=5733},questType="standard"},
[29182] = {id=29182,name="Flight of the Storm Crows",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="Many of the Druids of the Talon have made their way to the Molten Front, at your beckoning. You should go to Skylord Omnuron at Malfurion's Breach and see how their wings are faring in those burning skies.",starts={{npcID=50068,x=0.426,y=0.456,zoneID=616},{npcID=52669,x=0.272,y=0.624,zoneID=616}},ends={{npcID=52490,x=0.432,y=0.808,zoneID=5733}},coords={x=0.426,y=0.456,source="quest_giver",zoneID=616},questType="standard"},
[29184] = {id=29184,name="X Marks... Your Doom!",level=5,requiredLevel=5,faction="none",expansion=3,zoneID=3805,mapID=2437,description="How did those fools fail? I told them to be careful - even gave them disguises to help them blend in. Ahh, well. The bright side of their failure is that this opportunity falls to you. Succeed, and you'll be well on your way to joining my crew and sharing in the immeasurable fame that will soon be mine. Not that I need any more, mind you. There are yet a few portions of my map that require further exploration before our excavation can be initiated....",questType="dungeon"},
[29185] = {id=29185,name="Daily Tier 2 Heroic (1st)",level=35,requiredLevel=35,faction="none",expansion=3,questType="standard"},
[29186] = {id=29186,name="The Hex Lord's Fetish",level=35,requiredLevel=35,faction="both",expansion=3,zoneID=3805,description="Dis new warlord of da Amani, he be nothin' but an overgrown brute without da protection of a strong witch doctor and he has just dat. Da new warlord's ally be Hex Lord Malacrass, da most feared witch doctor to walk among da Amani in decades. Without da hex lord's say-so, Daakara won't be submitting his people to da control of da Zandalari. Defeat Hex Lord Malacrass, bring me his favorite fetish, and I be seein' that ya get a fittin' reward.",starts={{npcID=52925,x=0.138,y=0.522,zoneID=3805}},ends={{npcID=52925,x=0.138,y=0.522,zoneID=3805}},coords={x=0.138,y=0.522,source="quest_giver",zoneID=3805},questType="dungeon"},
[29187] = {id=29187,name="Tuskin' Raiders",level=5,requiredLevel=5,faction="none",expansion=3,zoneID=3805,mapID=2437,description="'Ey mon! You be new around 'ere, eh? Lemme ask a favor of ya. Budd's been refinin' his forest troll disguise. Says that he be close now - just be needin' one last touch. Tusks. My skinnin' talents be wasted 'ere. Somethin' about yankin' troll tusks be makin me queasy. Bring me back 10 troll tusks, eh mon?",questType="dungeon"},
[29189] = {id=29189,name="Wicked Webs",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="Some of our scouts have not reported back for duty. We fear they have succumbed to the deadly spiders in the vicinity. Hope may not be lost, however. The spiders often wrap up their live prey in cocoons for later consumption. Go search the pillars to the north for cocooned victims. You may yet be able to save some of our brethren.",starts={{npcID=52921,x=0.66,y=0.64,zoneID=5733}},ends={{npcID=52476,x=0.506,y=0.87,zoneID=5733},{npcID=52921,x=0.66,y=0.64,zoneID=5733}},coords={x=0.66,y=0.64,source="quest_giver",zoneID=5733},questType="standard"},
[29192] = {id=29192,name="The Wardens are Watching",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="We must tread carefully, . Fandral's Druids of the Flame practice their fiery magic beyond the pillars to the north. I need you to capture one of those druids alive for questioning. We must seize every opportunity to learn of their plans. One of my wardens will accompany you. Follow her instructions if you wish to survive.",starts={{npcID=52494,x=0.648,y=0.668,zoneID=5733}},ends={{npcID=52493,x=0.474,y=0.906,zoneID=5733},{npcID=52494,x=0.648,y=0.668,zoneID=5733}},coords={x=0.648,y=0.668,source="quest_giver",zoneID=5733},questType="standard"},
[29193] = {id=29193,name="On a Wing and a Prayer",level=35,requiredLevel=35,faction="both",expansion=3,zoneID=3537,description="Time well spent, mortal. While you struggled in the Plane of Fire, my watchers and I were able to determine when and, most importantly, where our vision was obscured. We discovered that the shroud was placed over the Nexus, far to the north in the realm of the blue dragonflight. I have attuned the Timeless Eye to show you the occurrences that remain hidden to us here. Bring it to Coldarra at once and seek out a place suitable for its activation. Go, child. Time is of the essence...",ends={{npcID=52835,x=0.344,y=0.252,zoneID=3537}},questType="standard"},
[29194] = {id=29194,name="Through a Glass, Darkly",level=10,requiredLevel=10,faction="both",expansion=3,zoneID=5786,description="Tarecgosa listens as you explain your presence in Coldarra.> Your tale rings true, . Much has changed since the death of Malygos - little of it for the better. I know of the device you carry, and I recognize Anachronos' magic in its creation. There is but one place in all of Coldarra that would allow this Timeless Eye to be used discreetly. You will require my assistance if you hope to succeed. Speak with me again inside the Nexus and you shall have it.",starts={{npcID=52835,x=0.344,y=0.252,zoneID=3537}},coords={x=0.344,y=0.252,source="quest_giver",zoneID=3537},questType="dungeon"},
[29195] = {id=29195,name="A Ritual of Flame",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=616,description="We appear to have everything under control. Our invasion portal to the Firelands will be opened momentarily, and the elementals have not put up much fight. Assist our druids by dispatching the last few of these elementals. Then, once the gate has been opened, we can make our move.",starts={{npcID=52838,x=0.27,y=0.546,zoneID=616}},ends={{npcID=52845,x=0.27,y=0.626,zoneID=616}},coords={x=0.27,y=0.546,source="quest_giver",zoneID=616},questType="standard"},
[29196] = {id=29196,name="To the Sanctuary!",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=616,description="We should not worry about this \"Druid of the Flame\" for the time being. We must be concerned with the continuance of our operation. Return to Matoclaw at the Sanctuary of Malorne. If Ragnaros was prepared for our arrival, then I anticipate that his forces will launch a counterattack soon.",starts={{npcID=52845,x=0.27,y=0.626,zoneID=616}},ends={{npcID=52669,x=0.272,y=0.624,zoneID=616}},coords={x=0.27,y=0.626,source="quest_giver",zoneID=616},questType="standard"},
[29197] = {id=29197,name="Caught Unawares",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=616,description="Our invasion plan looks to have backfired. Several of our birds have already reported in, speaking of fires breaking out across the vales of central Hyjal. Now, many of our druids are stranded out in the field, unprepared for such a large-scale attack. Thisalee was near Ashen Lake, and several others were out in the Regrowth, to the northeast. Go, ! Find them, and make sure that they do not succumb to this backdraft!",starts={{npcID=52669,x=0.272,y=0.624,zoneID=616}},ends={{npcID=52838,x=0.27,y=0.546,zoneID=616}},coords={x=0.272,y=0.624,source="quest_giver",zoneID=616},questType="standard"},
[29198] = {id=29198,name="The Sanctuary Must Not Fall",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=616,description="Malfurion is working on a miracle for us. He believes that, in this time of peril, he can resurrect Malorne to protect the Sanctuary. I have faith in him. In the meantime, we need to hold this perimeter. Stand by, and make sure no harm befalls my fellow arch druid.",starts={{npcID=52838,x=0.27,y=0.546,zoneID=616}},ends={{npcID=52845,x=0.27,y=0.626,zoneID=616}},coords={x=0.27,y=0.546,source="quest_giver",zoneID=616},questType="standard"},
[29199] = {id=29199,name="Calling for Reinforcements",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=616,description="We suffered heavy losses during the backdraft after our invasion attempt. Our second attempt cannot fail. We need reinforcements before we attempt another invasion. Please, , work with Matoclaw to obtain enough resources to afford reinforcements. Then, we take our second and final stab at the Firelands.",starts={{npcID=52838,x=0.27,y=0.546,zoneID=616}},ends={{npcID=52838,x=0.27,y=0.546,zoneID=616}},coords={x=0.27,y=0.546,source="quest_giver",zoneID=616},questType="standard"},
[29200] = {id=29200,name="Leyara",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=616,description="Before we depart, , I have another matter to which you should attend. A Druid of the Flame has been spotted in the ruins to the northwest. I suspect it is the same one that attacked us at the portal several days ago. Now would be an ideal time to see what it is that she truly wants... and if necessary, dispose of her. See to this flame druid, then we can continue on our planned course.",starts={{npcID=52838,x=0.27,y=0.546,zoneID=616}},ends={{npcID=52669,x=0.272,y=0.624,zoneID=616}},coords={x=0.27,y=0.546,source="quest_giver",zoneID=616},questType="standard"},
[29201] = {id=29201,name="Through the Gates of Hell",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="There will be time to mourn for Hamuul later. His is the first of many inevitable casualties in this war.... but our attack cannot wait, nor should the momentum we have gained over the last several days be wasted. The portal atop Nordune Ridge is now open. Our reinforcements are prepared, and they await only my order to pass through the portal. We will meet again on the other side of the portal. Once there, we shall ensure that our foothold is secure.",starts={{npcID=52845,x=0.27,y=0.626,zoneID=616}},ends={{npcID=52135,x=0.47,y=0.91,zoneID=5733}},coords={x=0.27,y=0.626,source="quest_giver",zoneID=616},questType="standard"},
[29202] = {id=29202,name="The Fate of Runetotem",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=616,description="I apologize for speaking curtly with you earlier. The loss of Hamuul was shocking to me, and difficult to cope with. They brought in his body while you were away. He is alive, but - as you might imagine - he is very, very badly burned. The scars are deep. He may not live. I have arranged for some of our finest healers to attend to him. If it is not too much to ask, would you speak with Dorda'en Nightweaver ? He and his fellow attendants may need your help.",starts={{npcID=52669,x=0.272,y=0.624,zoneID=616}},ends={{npcID=52986,x=0.274,y=0.624,zoneID=616}},coords={x=0.272,y=0.624,source="quest_giver",zoneID=616},questType="standard"},
[29203] = {id=29203,name="Into the Depths",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="Leyara has been spotted in the Igneous Depths. A group of Shadow Wardens has cornered her. Go there immediately. I will join you as soon as I make one necessary preparation.",starts={{npcID=52135,x=0.47,y=0.91,zoneID=5733}},ends={{npcID=52135,x=0.47,y=0.91,zoneID=5733}},coords={x=0.47,y=0.91,source="quest_giver",zoneID=5733},questType="standard"},
[29204] = {id=29204,name="The Warden's Charge",level=5,requiredLevel=5,faction="none",expansion=3,zoneID=5733,description="Captain Saynna Stormrunner is launching an attack against the Forlorn Spire. If you head to the northeast, you'll find her at the bottom of the ramp leading up towards that rise. I've assigned her a large number of our men, but her chances of success would be greatly increased if you join her cause. It's your decision, .",starts={{npcID=52824,x=0.458,y=0.858,zoneID=5733}},ends={{npcID=52493,x=0.474,y=0.906,zoneID=5733}},coords={x=0.458,y=0.858,source="quest_giver",zoneID=5733},questType="standard"},
[29205] = {id=29205,name="The Forlorn Spire",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="Captain Saynna Stormrunner is launching an attack against the Forlorn Spire. If you head to the northeast, you'll find her at the bottom of the ramp leading up towards that rise. Go there and escort one of her druids to the tower with any forces that she can spare. You'll have quite a fight ahead of you - make sure the druid lives to see the end of it or they'll not be able to seize the tower.",starts={{npcID=52824,x=0.458,y=0.858,zoneID=5733}},ends={{npcID=52494,x=0.648,y=0.668,zoneID=5733}},coords={x=0.458,y=0.858,source="quest_giver",zoneID=5733},questType="standard"},
[29206] = {id=29206,name="Into the Fire",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="Skylord Omnuron and his druids are seeking to push through the Furnace to our northwest. They've been able to fly over the dangers, but they really need someone on the ground to help them secure the territory past the fire... someone like you. If you want to aid the Druids of the Talon, wait for one of Omnuron's Windcallers to start pushing through the fire, stay close to him, and keep him safe from any attackers within the flames.",starts={{npcID=52824,x=0.458,y=0.858,zoneID=5733}},ends={{npcID=52444,x=0.424,y=0.598,zoneID=5733}},coords={x=0.458,y=0.858,source="quest_giver",zoneID=5733},questType="standard"},
[29208] = {id=29208,name="An Old Friend",level=35,requiredLevel=35,faction="both",expansion=3,zoneID=1977,mapID=210,starts={{npcID=52877,x=0.612,y=0.814,mapID=210}},ends={{npcID=52877,x=0.612,y=0.814,mapID=210}},coords={x=0.612,y=0.814,source="quest_giver",mapID=210},questType="standard"},
[29209] = {id=29209,name="Into the Fiery Depths",level=5,requiredLevel=5,faction="none",expansion=3,zoneID=5733,description="One of our druids moved ahead into the Igneous Depths in pursuit of a Druid of the Flame. Go to her. Help her.",starts={{npcID=52494,x=0.648,y=0.668,zoneID=5733}},ends={{npcID=52825,x=0.53,y=0.906,zoneID=5733}},coords={x=0.648,y=0.668,source="quest_giver",zoneID=5733},questType="standard"},
[29210] = {id=29210,name="Enduring the Heat",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="Shalis has gone with one of our druids to stop a Druid of the Flame that is performing a summoning ritual in the Igneous Depths, below us. They have been tasked with killing the druid, but I need you to stop the ritual. You'll find the entrance to the cavern east of the Magma Springs. Once inside, you'll see 8 blue runes spread throughout the cavern. You can use these runes to protect you from the fiery creatures, but you need to stamp all of them out to end the ritual. You will need to be swift.",starts={{npcID=52494,x=0.648,y=0.668,zoneID=5733}},ends={{npcID=52823,x=0.578,y=0.496,zoneID=5733},{npcID=52825,x=0.53,y=0.906,zoneID=5733}},coords={x=0.648,y=0.668,source="quest_giver",zoneID=5733},questType="standard"},
[29211] = {id=29211,name="Solar Core Destruction",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="The fight has taken us to Fandral's doorstep. His druids are channeling energies of the Firelands into a vessel called the Solar Core. Should this vessel detonate on Azeroth, none of us will have a home to return to. We need to strike at the Solar Core now, while it is still vulnerable. You can find the infernal device to the northeast.",starts={{npcID=52494,x=0.648,y=0.668,zoneID=5733}},ends={{npcID=52493,x=0.474,y=0.906,zoneID=5733},{npcID=52494,x=0.648,y=0.668,zoneID=5733}},coords={x=0.648,y=0.668,source="quest_giver",zoneID=5733},questType="standard"},
[29213] = {id=29213,name="How's the Hunter Holding Up?",level=35,requiredLevel=35,faction="alliance",expansion=3,zoneID=33,description="Tings ain't looking good. Dat panther was under some powerful magic. We better check on dat hunter an' see how he be doin'.",ends={{npcID=52371,x=0.76,y=0.666,zoneID=33}},questType="standard"},
[29214] = {id=29214,name="The Shadow Wardens",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=616,description="The Shadow Wardens are back in the Regrowth. I know that they take the loss of Fandral from their custody very seriously, so it wouldn't take much prodding to bring them to the Firelands to hunt the Druids of the Flame, and perhaps aid us otherwise in the process. Should you come upon enough marks, you should seek out Captain Saynna Stormrunner at the Sanctuary of Malorne and secure her aid.",starts={{npcID=52135,x=0.47,y=0.91,zoneID=5733}},ends={{npcID=52844,x=0.268,y=0.62,zoneID=616}},coords={x=0.47,y=0.91,source="quest_giver",zoneID=5733},questType="standard"},
[29215] = {id=29215,name="The Hunt Begins",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="The Shadow Wardens have joined the fight at the Molten Front, on your request. You should find Captain Saynna Stormrunner and see to it that they've found a way to best apply their skills.",starts={{npcID=52669,x=0.272,y=0.624,zoneID=616}},ends={{npcID=52493,x=0.474,y=0.906,zoneID=5733}},coords={x=0.272,y=0.624,source="quest_giver",zoneID=616},questType="standard"},
[29217] = {id=29217,name="The Captive Scouts",level=35,requiredLevel=35,faction="both",expansion=3,zoneID=3805,description="After we arrived, I dispatched my scouts to learn more about da Zandalari presence here in Zul'Aman . Many returned with useful information, but four still be missin'. If we do not act quickly, da new warlord's lieutenants will offer dem as sacrifices in honor of da Zandalari emissaries. Find my scouts, , and free dem before da priests offer dem as sacrifices!",starts={{npcID=52933,x=0.138,y=0.538,zoneID=3805}},ends={{npcID=52933,x=0.138,y=0.538,zoneID=3805}},coords={x=0.138,y=0.538,source="quest_giver",zoneID=3805},questType="dungeon"},
[29219] = {id=29219,name="Bwemba's Spirit",level=35,requiredLevel=35,faction="horde",expansion=3,zoneID=1637,description="Dese be troublin' times for us Darkspear. Da Zandalar be reuniting all da troll clans an' plan to take back da lands dey lost. We tryin' to warn all dat we can. But it might be too late. Another Darkspear gone down to Stranglethorn to warn da people. But it ain't safe to travel alone in Stranglethorn. Help me find him and make sure da people in Stranglethorn are warned of da rise of da troll tribes. I gonna bind my spirit wit' ya. When ya get to Stranglethorn, I be able to aid ya.",starts={{npcID=53081,x=0.326,y=0.682,zoneID=1637}},coords={x=0.326,y=0.682,source="quest_giver",zoneID=1637},questType="standard"},
[29220] = {id=29220,name="To Bambala",level=35,requiredLevel=35,faction="horde",expansion=3,zoneID=33,description="Da first place we check gonna be da place most likely to be attacked first, Bambala. Bambala be dangerously close to da troll city Zul'Gurub... It make for an easy target. Maybe we find da emissary dere. Hopefully it ain't too late.",starts={{npcID=53081,x=0.326,y=0.682,zoneID=1637}},ends={{npcID=52980,x=0.646,y=0.404,zoneID=33}},coords={x=0.326,y=0.682,source="quest_giver",zoneID=1637},questType="standard"},
[29221] = {id=29221,name="Serpents and Poison",level=35,requiredLevel=35,faction="horde",expansion=3,zoneID=33,description="Da warning helped, . We gathered more Headhunters to help defend. But Headhunters... Dey not used to hunting heads on serpents. So we soon be overwhelmed. Dese serpents, dey seem to come from everywhere. An' it probably only gonna get worse. Help us and kill da serpents and have Bwemba use her mojo to cure da ones dat are sick from poison.",starts={{npcID=52980,x=0.646,y=0.404,zoneID=33}},ends={{npcID=52980,x=0.646,y=0.404,zoneID=33}},coords={x=0.646,y=0.404,source="quest_giver",zoneID=33},questType="standard"},
[29222] = {id=29222,name="Spirits Are With Us",level=35,requiredLevel=35,faction="horde",expansion=3,zoneID=33,description="Dere was something about da way da serpents attacked, . Something unnatural... Even da poison had a hint of some bad mojo. Dere be a shrine near here wit' a bonfire. We can use dat to perform a ritual. Whatever be makin' dese serpents attack, dey probably still watchin' over dem. Da only problem, , is dat I only be here in spirit form. I need you to be my hands. I need you to go to da fire an' prepare it for me. Den I'll handle da rest.",questType="standard"},
[29223] = {id=29223,name="Nesingwary Will Know",level=35,requiredLevel=35,faction="horde",expansion=3,zoneID=33,description="So da Gurubashi be on da rampage an' dey usin' serpents to lead da charge. You know who be good at keepin' da animal population in check? Da hunters at Nesingwary's Expedition. Head over dere and see how dey doin'. See if dey know a good way to get rid of da serpents. If dey don't know, den you gotta at least warn dem dat dese serpents, it ain't all natural.",starts={{npcID=52980,x=0.646,y=0.404,zoneID=33}},ends={{npcID=52294,x=0.44,y=0.23,zoneID=33}},coords={x=0.646,y=0.404,source="quest_giver",zoneID=33},questType="standard"},
[29225] = {id=29225,name="Actionable Intelligence",level=35,requiredLevel=35,faction="both",expansion=3,zoneID=616,description="Tarecgosa listens intently as you describe your vision.> Impossible! Not even Arygos would dare to go to such lengths. I do not question your integrity, , but you must understand - your mortal mind can easily be deceived. Regardless, Kalecgos must be informed of these events. You must travel to Nordrassil at once to seek him out. I shall remain here to conceal the evidence of our activities. Speak of this to no one else!",ends={{npcID=52995,x=0.622,y=0.232,zoneID=616}},questType="standard"},
[29226] = {id=29226,name="Track the Tracker",level=35,requiredLevel=35,faction="horde",expansion=3,zoneID=33,description="We've been fending off serpents for days now, . But the serpents are nothing compared to what else is out in that jungle. We hunters are being hunted. A large panther named Mauti has been dragging my men off into the bush. We sent Grent Direhammer , one of our best hunters, to track this beast down. Direhammer headed off to the east, perhaps you can find them there.",starts={{npcID=52294,x=0.44,y=0.23,zoneID=33}},ends={{npcID=52346,x=0.502,y=0.216,zoneID=33}},coords={x=0.44,y=0.23,source="quest_giver",zoneID=33},questType="standard"},
[29227] = {id=29227,name="The Hunter's Revenge",level=35,requiredLevel=35,faction="horde",expansion=3,zoneID=33,description="The beast that's been hunting us... I've been hunting it. We call him Mauti. He's a clever one. But he made a grave mistake when he killed my brother. Now that mistake is going to cost him. Ol' Direhammer has got his scent. I've noticed him roaming just above Kurzen's Compound. If we act fast, we can take him down. Are you ready, ?",starts={{npcID=52294,x=0.44,y=0.23,zoneID=33},{npcID=52346,x=0.502,y=0.216,zoneID=33}},coords={x=0.44,y=0.23,source="quest_giver",zoneID=33},questType="standard"},
[29229] = {id=29229,name="Follow That Cat",level=35,requiredLevel=35,faction="horde",expansion=3,zoneID=33,description="Well, that explains why Mauti seemed smaller... The real Mauti has run off with Grent Direhammer, but being the wise hunter that he is, he has fired flares off so you can track him. Find Direhammer before it's too late!",starts={{npcID=208365,x=0.646,y=0.22,zoneID=33}},coords={x=0.646,y=0.22,source="quest_giver",zoneID=33},questType="standard"},
[29230] = {id=29230,name="Mauti",level=35,requiredLevel=35,faction="horde",expansion=3,zoneID=33,description="I got da feeling dat somethin' ain't right wit' dat panther, . It ain't natural. I gonna need to perform some rituals over da body. Put Mauti down, an' den let's see what we can find out, .",questType="standard"},
[29231] = {id=29231,name="How's the Hunter Holding Up?",level=35,requiredLevel=35,faction="horde",expansion=3,zoneID=33,description="Tings ain't looking good. Dat panther was under some powerful magic. We better check on dat hunter an' see how he be doin'.",ends={{npcID=52371,x=0.76,y=0.666,zoneID=33}},questType="standard"},
[29232] = {id=29232,name="Bury Me With Me Boots...",level=35,requiredLevel=35,faction="horde",expansion=3,zoneID=33,description="Ah... It's you, . Mauti... He's dead? Then my brother has been avenged. I've only one request from ya... This scamp here, he's been pawing at me bare feet. No dwarf should go to the earth with bare feet. Please, bury me with me boots.",starts={{npcID=52371,x=0.76,y=0.666,zoneID=33}},ends={{npcID=52371,x=0.76,y=0.666,zoneID=33}},coords={x=0.76,y=0.666,source="quest_giver",zoneID=33},questType="standard"},
[29233] = {id=29233,name="Warn Grom'gol",level=35,requiredLevel=35,faction="horde",expansion=3,zoneID=33,description="Dis death ain't be in vain, . We figure out dat Kilnara be on da prowl. Tings don't look good. We better check out Grom'gol Base Camp to da west. Maybe we find my contact dere.",ends={{npcID=52996,x=0.384,y=0.502,zoneID=33}},questType="standard"},
[29234] = {id=29234,name="Delegation",level=35,requiredLevel=35,faction="both",expansion=3,zoneID=3537,description="I am duty-bound to look into your claims immediately, , which means my mission here now must fall to you. A surge of ancient magic, far too strong to have occurred naturally, drew me here. I have since discovered a most troubling development. A bough from Nordrassil has been ripped from the tree and taken deep into the Firelands. There, a powerful ritual threatens to corrupt Nordrassil, consuming it in flame. You must find a way to interrupt the ritual and reclaim the World Tree's branch.",starts={{npcID=52995,x=0.622,y=0.232,zoneID=616}},ends={{npcID=53009,x=0.464,y=0.354,zoneID=3537}},coords={x=0.622,y=0.232,source="quest_giver",zoneID=616},questType="raid"},
[29235] = {id=29235,name="Defend Grom'gol",level=35,requiredLevel=35,faction="horde",expansion=3,zoneID=33,description="I hope you like to fight, . Your troll friend has been through here and warned us that the Gurubashi were on the rampage. I never thought the battle would be this glorious though. Come, join in our fight and let's show these Gurubashi trolls the might of the Horde!",starts={{npcID=52996,x=0.384,y=0.502,zoneID=33}},ends={{npcID=52996,x=0.384,y=0.502,zoneID=33}},coords={x=0.384,y=0.502,source="quest_giver",zoneID=33},questType="standard"},
[29236] = {id=29236,name="To Hardwrench Hideaway",level=35,requiredLevel=35,faction="horde",expansion=3,zoneID=33,description="Bwemba ... Is that you? Your contact was here. He was eager to get to the next location and warn them. And really, who could blame him? I gave him use of a wyvern to reach the goblins of Hardwrench Hideaway, in the Cape of Stranglethorn. I will give you use of one of my wyverns to reach Hardwrench. Talk to me when you are ready to go, .",starts={{npcID=53008,x=0.39,y=0.512,zoneID=33}},coords={x=0.39,y=0.512,source="quest_giver",zoneID=33},questType="standard"},
[29237] = {id=29237,name="Voodoo Zombies",level=35,requiredLevel=35,faction="horde",expansion=3,zoneID=33,description="Da people... Dey all zombies, voodoo zombies! Dis ain't gonna be pretty, . You gotta kill dem. But once dey killed, dere is a moment where I can save dem. Change dem back into da person dey were before. We gotta act fast. Da zombies don' rest.",questType="standard"},
[29238] = {id=29238,name="Bad Supplies",level=35,requiredLevel=35,faction="horde",expansion=3,zoneID=33,description="Some of da survivors mentioned food, . We better check da food supplies. I gotta a bad feelin' about dis.",questType="standard"},
[29239] = {id=29239,name="Nordrassil's Bough",level=35,requiredLevel=35,faction="both",expansion=3,zoneID=3537,description="Much has transpired since last we spoke. I have taken it upon myself to visit the Nexus and recover Anachronos's artifact, but not before using it for myself. Now I too have witnessed that which you have seen. Before discussing the matter further, allow me to express my gratitude to you for your assistance, both here and in the Plane of Fire.",starts={{npcID=53009,x=0.464,y=0.354,zoneID=3537}},ends={{npcID=54233,x=0.46,y=0.348,zoneID=3537}},coords={x=0.464,y=0.354,source="quest_giver",zoneID=3537},questType="standard"},
[29240] = {id=29240,name="Emergency Extraction",level=35,requiredLevel=35,faction="both",expansion=3,zoneID=3537,description="Now, back to the matter at hand... I am convinced that the vision in the Nexus is one of Deathwing's illusions designed to bring conflict into our flight at a very fragile time. The Worldbreaker would only be strengthened were we to fall to infighting. Still, a gnawing sense of unease tempts me to take a path of caution. It would be wise for me to take Tarecgosa and withdraw until the time of choosing.",starts={{npcID=53009,x=0.464,y=0.354,zoneID=3537}},ends={{npcID=53149,x=0.31,y=0.24,zoneID=3537}},coords={x=0.464,y=0.354,source="quest_giver",zoneID=3537},questType="standard"},
[29241] = {id=29241,name="Break the Godbreaker",level=35,requiredLevel=35,faction="both",expansion=3,zoneID=1977,description="Bloodslayer Zala points at the temple in the distance.> When Jin'do was last ripped from dis world, he survived as a shade, weak and broken, in da spirit world. But Jin'do always had power over da spirits. One by one, he broke dem to his will, and wit' each soul devoured, Jin'do got closer ta' rippin' a hole through to dis world. Ta be here now... Da spirits be wit' us, we must end Jin'do.",starts={{npcID=53024,x=0.306,y=0.474,zoneID=1977}},ends={{npcID=53024,x=0.306,y=0.474,zoneID=1977}},coords={x=0.306,y=0.474,source="quest_giver",zoneID=1977},questType="dungeon"},
[29242] = {id=29242,name="Putting a Price on Priceless",level=35,requiredLevel=35,faction="both",expansion=3,zoneID=1977,description="Listen, friend. I don't know you, and you don't know me. But as long as we're both here, there's something Revilgaz wanted me to mention. Maybe you're taking a stroll through this troll-infested jungle-ocalypse. Maybe you happen to find a priceless troll artifact or two. Maybe you bring it back to me and I accidentally leave behind a little present for ya'. If you must know, it's for a project. And no, you can't ask what the project is.",starts={{npcID=53043,x=0.306,y=0.508,zoneID=1977}},ends={{npcID=53043,x=0.306,y=0.508,zoneID=1977}},coords={x=0.306,y=0.508,source="quest_giver",zoneID=1977},questType="dungeon"},
[29243] = {id=29243,name="Strike at the Heart",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="One of Ragnaros' Lieutenants has shown itself at Ragnaros' Reach. It is time to strike. Captain Saynna has requested that you be there to help see the fight through. Witherbranch and some others will have joined the battle by the time you arrive. You should make haste to the northwest and find them.",starts={{npcID=52495,x=0.516,y=0.82,zoneID=5733},{npcID=53056,x=0.576,y=0.496,zoneID=5733}},ends={{npcID=52493,x=0.474,y=0.906,zoneID=5733}},coords={x=0.516,y=0.82,source="quest_giver",zoneID=5733},questType="standard"},
[29244] = {id=29244,name="A Lieutenant of Flame",level=5,requiredLevel=5,faction="none",expansion=3,zoneID=5733,description="Captain Saynna has requested your presence at Ragnaros' Reach. A Lieutenant of Flame has shown himself and she thinks you are our greatest chance at striking against him. Make your way there as soon as you're able.",starts={{npcID=52493,x=0.474,y=0.906,zoneID=5733}},ends={{npcID=52495,x=0.516,y=0.82,zoneID=5733}},coords={x=0.474,y=0.906,source="quest_giver",zoneID=5733},questType="standard"},
[29245] = {id=29245,name="The Mysterious Seed",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="A small, dried acorn has fallen out of the Flame Druid's robe. Why would a Druid of the Flame be carrying it around? Perhaps someone at Malfurion's Breach would like to see it.",starts={{npcID=208535,x=0.701,y=0.396,zoneID=5733}},ends={{npcID=52489,x=0.506,y=0.87,zoneID=5733}},coords={x=0.701,y=0.396,source="quest_giver",zoneID=5733},questType="standard"},
[29249] = {id=29249,name="Planting Season",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="The acorn seems to be unharmed. Avrilla shrugs.> No point in beating around the bush. Let's plant it and see what comes out. Luckily for you, we brought some leftover soil with us to help establish our base. You'll find the soil at the graveyard directly east.",starts={{npcID=52489,x=0.506,y=0.87,zoneID=5733}},ends={{npcID=52489,x=0.506,y=0.87,zoneID=5733}},coords={x=0.506,y=0.87,source="quest_giver",zoneID=5733},questType="standard"},
[29250] = {id=29250,name="Making Contact",level=35,requiredLevel=35,faction="horde",expansion=3,zoneID=5287,description="You aren't one of the zombies... A troll? I did see one, just before the outbreak... He warned us, told us to be on our guard... But it was too late. Your troll friend headed to Booty Bay to warn them...",starts={{npcID=53078,x=0.334,y=0.302,zoneID=5287}},ends={{npcID=52767,x=0.41,y=0.732,zoneID=5287}},coords={x=0.334,y=0.302,source="quest_giver",zoneID=5287},questType="standard"},
[29251] = {id=29251,name="Booty Bay's Interests",level=35,requiredLevel=35,faction="horde",expansion=3,zoneID=1977,description="Look, . You've helped out plenty so far, but that's not going to be enough. I need these crazy trolls stopped, or at least stopped from getting into Booty Bay. I'm going to send a man in to oversee the action, but I want you to go into Zul'Gurub and make something happen. At the very least, I want you to find me something that will help keep these trolls out of Booty Bay. You do that and we'll treat you right.",starts={{npcID=2496,x=0.41,y=0.73,zoneID=5287}},ends={{npcID=2496,x=0.41,y=0.73,zoneID=5287},{npcID=53151,x=0.306,y=0.476,zoneID=1977}},coords={x=0.41,y=0.73,source="quest_giver",zoneID=5287},questType="dungeon"},
[29252] = {id=29252,name="Booty Bay's Interests",level=35,requiredLevel=35,faction="horde",expansion=3,zoneID=5287,description="I've been sent here by Baron Revilgaz of Booty Bay to make sure this troll menace is halted. Or that it is at least halted at the gates of Booty Bay. I want action and I want results. I want you to get in there and kill. I want you to get in there and find me something that will help keep these trolls out of Booty Bay. You do that and we'll make sure you get paid.",starts={{npcID=53151,x=0.306,y=0.476,zoneID=1977}},ends={{npcID=53151,x=0.306,y=0.476,zoneID=1977},{npcID=2496,x=0.41,y=0.73,zoneID=5287}},coords={x=0.306,y=0.476,source="quest_giver",zoneID=1977},questType="dungeon"},
[29253] = {id=29253,name="A Shiny Reward",level=35,requiredLevel=35,faction="horde",expansion=3,zoneID=1977,description="There is a stash of loot located in the statue on Janeiro's Point just northwest of Booty Bay in Stranglethorn Vale. Head to the statue and claim your prize, .",starts={{npcID=2496,x=0.41,y=0.73,zoneID=5287},{npcID=53151,x=0.306,y=0.476,zoneID=1977}},ends={{npcID=208420,x=0.355,y=0.636,zoneID=5287}},coords={x=0.41,y=0.73,source="quest_giver",zoneID=5287},questType="standard"},
[29254] = {id=29254,name="Little Lasher",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="The little red flower wiggles its tendrils happily. It seems to like you! Perhaps Avrilla would like to see what grew out of the acorn.",starts={{npcID=52489,x=0.506,y=0.87,zoneID=5733}},ends={{npcID=52489,x=0.506,y=0.87,zoneID=5733}},coords={x=0.506,y=0.87,source="quest_giver",zoneID=5733},questType="standard"},
[29261] = {id=29261,name="Zul'Aman Voodoo",level=30,requiredLevel=30,faction="both",expansion=3,zoneID=3805,starts={{npcID=208549,x=0.313,y=0.484,zoneID=1977},{npcID=208549,x=0.157,y=0.56,zoneID=3805}},ends={{npcID=208549,x=0.313,y=0.484,zoneID=1977},{npcID=208549,x=0.157,y=0.56,zoneID=3805}},coords={x=0.313,y=0.484,source="quest_giver",zoneID=1977},questType="dungeon"},
[29262] = {id=29262,name="Zul'Gurub Voodoo",level=30,requiredLevel=30,faction="both",expansion=3,zoneID=1977,starts={{npcID=208550,x=0.313,y=0.484,zoneID=1977}},ends={{npcID=208550,x=0.313,y=0.484,zoneID=1977}},coords={x=0.313,y=0.484,source="quest_giver",zoneID=1977},questType="dungeon"},
[29263] = {id=29263,name="A Bitter Pill",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="As far as I'm concerned, there's no problem that can't be solved with bombs. And if a bomb doesn't solve your problem on the first try... use a bigger bomb. So there's this big worm that's been eating people near the lava pools up north. Search for breath bubbles to find it. Attack it until it prepares to bite, then place this bomb down in front of it. Then sit back and watch the fireworks. Hmm... there was one other thing I wanted to say... oh yeah! Don't get eaten.",starts={{npcID=53196,x=0.468,y=0.902,zoneID=5733}},ends={{npcID=53214,x=0.47,y=0.9,zoneID=5733}},coords={x=0.468,y=0.902,source="quest_giver",zoneID=5733},questType="standard"},
[29264] = {id=29264,name="Flamewakers of the Molten Flow",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="Of all Ragnaros' minions, the flamewakers appear to be the most devoted. Most of them dwell within this cave, preparing for another attack. Our foothold may be strong, but we will not tolerate any surprise attacks from these worms. No, we will strike first. Tear them apart, .",starts={{npcID=52444,x=0.424,y=0.598,zoneID=5733}},ends={{npcID=52444,x=0.424,y=0.598,zoneID=5733},{npcID=52467,x=0.486,y=0.86,zoneID=5733}},coords={x=0.424,y=0.598,source="quest_giver",zoneID=5733},questType="standard"},
[29267] = {id=29267,name="Some Good Will Come",level=35,requiredLevel=35,faction="alliance",expansion=3,zoneID=33,description="So much violence, so much death. Brothers have died, a mother has died, and now a panther cub will die if there is no one to take care of it. Will you take a pause from the violence to help care for a panther cub ?",ends={{npcID=52374,x=0.76,y=0.666,zoneID=33}},questType="standard"},
[29268] = {id=29268,name="Some Good Will Come",level=35,requiredLevel=35,faction="horde",expansion=3,zoneID=33,description="So much violence, so much death. Brothers have died, a mother has died, and now a panther cub will die if there is no one to take care of it. Will you take a break from the violence and help care for a panther cub ?",ends={{npcID=52374,x=0.76,y=0.666,zoneID=33}},questType="standard"},
[29269] = {id=29269,name="At One",level=35,requiredLevel=35,faction="both",expansion=3,zoneID=3537,description="I was charged with her protection, yet it was she who sacrificed herself for my sake. I cannot bear to lose her, . I must make a solemn request of you. Never has a mortal borne the essence of a true dragon, but with your permission I would make an exception. Please, while there is life in her, will you allow me to bind Tarecgosa to you?",starts={{npcID=53149,x=0.31,y=0.24,zoneID=3537}},ends={{npcID=53210,x=0.31,y=0.24,zoneID=3537}},coords={x=0.31,y=0.24,source="quest_giver",zoneID=3537},questType="standard"},
[29272] = {id=29272,name="Need... Water... Badly...",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="Need... water... badly...",starts={{npcID=53233,x=0.518,y=0.31,zoneID=5733}},ends={{npcID=52477,x=0.512,y=0.852,zoneID=5733}},coords={x=0.518,y=0.31,source="quest_giver",zoneID=5733},questType="standard"},
[29273] = {id=29273,name="How Hot",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="The fire hawks of Fireplume Peak can withstand incredible temperatures. While you'll often find them circling the skies above, they're also known to swim in molten lava. Isn't that right, Anren? We'd like to know just how hot that lava can get. Fireplume Peak has three large lava pools. Use this to measure the temperature of each.",starts={{npcID=52477,x=0.512,y=0.852,zoneID=5733}},ends={{npcID=52478,x=0.42,y=0.612,zoneID=5733}},coords={x=0.512,y=0.852,source="quest_giver",zoneID=5733},questType="standard"},
[29275] = {id=29275,name="Fandral's Methods",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="The Druids of the Flame... an order of druids that, up until a few weeks ago, Tholo and I had never even heard of. Now, under the leadership of Fandral Staghelm, they threaten our mission's success with their mastery of fire. It would appear that they store some supplies in the Igneous Depths, to the northeast. Perhaps, if we can get some of those supplies, we will have more luck when we take the fight to Fandral.",starts={{npcID=52478,x=0.42,y=0.612,zoneID=5733}},ends={{npcID=52477,x=0.512,y=0.852,zoneID=5733}},coords={x=0.42,y=0.612,source="quest_giver",zoneID=5733},questType="standard"},
[29276] = {id=29276,name="The Flame Spider Queen",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="The Widow's Clutch, to the northeast, is named after Beth'tilac, the enormous queen of the flame spiders. Her webs and her poison are a nagging threat to our main offensive force. We believe that if we study the flame spiders here on the Molten Front, we can use that information to find success against Beth'tilac. Use whatever methods you can to gather their venom and their web fluid, then return to my trusted friend Anren.",starts={{npcID=52477,x=0.512,y=0.852,zoneID=5733}},ends={{npcID=52478,x=0.42,y=0.612,zoneID=5733}},coords={x=0.512,y=0.852,source="quest_giver",zoneID=5733},questType="standard"},
[29278] = {id=29278,name="Living Obsidium",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="Have you seen those fireballs falling out of the sky? I saw one crash in the fields to the north, and the rock that landed was made of pure Living Obsidium! I can use the material to craft ultra-sturdy heat proof armor and weapons for our troops. Can you bring me a lode? Go to the Magma Springs and touch one of the magnetic stones. Just watch where you're standing when the rain of fire hits, and gather up the rocks before they crumble from the impact.",starts={{npcID=53196,x=0.468,y=0.902,zoneID=5733}},ends={{npcID=53214,x=0.47,y=0.9,zoneID=5733}},coords={x=0.468,y=0.902,source="quest_giver",zoneID=5733},questType="standard"},
[29279] = {id=29279,name="Filling the Moonwell",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=616,description="We've constructed this moonwell, but it serves little purpose until it is filled with the sacred waters of the Well of Eternity. With an active moonwell, we would be able to bless our food stores, and we may also be able to use the blessing to offer you some protection from fire as well. When you've obtained enough marks, speak to Matoclaw at the Sanctuary of Malorne. She'll be able to secure transport of the sacred waters.",starts={{npcID=53881,x=0.442,y=0.862,zoneID=5733}},ends={{npcID=52669,x=0.272,y=0.624,zoneID=616}},coords={x=0.442,y=0.862,source="quest_giver",zoneID=5733},questType="standard"},
[29280] = {id=29280,name="Nourishing Waters",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="I have dispatched the sacred moonwell waters to Malfurion's Breach, as you requested. Ayla is well trained in tending to them. You should return to her and see the boons she weaves for you there.",starts={{npcID=52669,x=0.272,y=0.624,zoneID=616}},ends={{npcID=53881,x=0.442,y=0.862,zoneID=5733}},coords={x=0.272,y=0.624,source="quest_giver",zoneID=616},questType="standard"},
[29282] = {id=29282,name="Well Armed",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="Ricket should be at Malfurion's Breach with Damek, as you requested. I'm not sure you fully know what you're getting into with those two though. Speaking of which, you should probably go check on them... make sure they haven't managed to blow up the Sentinel Tree itself. As long as you keep them busy with the elementals, the chances of \"accidents\" at the breach should lessen dramatically.",starts={{npcID=52669,x=0.272,y=0.624,zoneID=616}},ends={{npcID=53196,x=0.468,y=0.902,zoneID=5733},{npcID=53304,x=0.36,y=0.566,zoneID=5733},{npcID=54163,x=0.662,y=0.654,zoneID=5733}},coords={x=0.272,y=0.624,source="quest_giver",zoneID=616},questType="standard"},
[29283] = {id=29283,name="Calling the Ancients",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=616,description="The ancients await in Hyjal. The Firelands will prove a dangerous place for them considering their... composition, but their strength will be of great use to us if we are to face any of Ragnaros' lieutenants. Gather your marks, and seek out Elderlimb at the Sanctuary of Malorne. If they are to march with us, he would be the one leading them through the portal.",starts={{npcID=53882,x=0.444,y=0.884,zoneID=5733}},ends={{npcID=52906,x=0.26,y=0.612,zoneID=616}},coords={x=0.444,y=0.884,source="quest_giver",zoneID=5733},questType="standard"},
[29284] = {id=29284,name="Aid of the Ancients",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="The ancients have seen the value of your wisdom, and have set root at Malfurion's Breach. You should seek out Elderlimb . I am certain he would like to hear from you.",starts={{npcID=52669,x=0.272,y=0.624,zoneID=616}},ends={{npcID=52488,x=0.44,y=0.886,zoneID=5733}},coords={x=0.272,y=0.624,source="quest_giver",zoneID=616},questType="standard"},
[29285] = {id=29285,name="Alignment",level=35,requiredLevel=35,faction="both",expansion=3,zoneID=3537,description="The time of choosing has arrived, . While only members of the blue dragonflight may attend, Tarecgosa's binding makes your presence requisite. I must ask that you take on her form and vote on her behalf. Do not tarry. The moment of the eclipse draws near....",starts={{npcID=53215,x=0.23,y=0.308,zoneID=3537}},ends={{npcID=53349,x=0.232,y=0.228,zoneID=3537}},coords={x=0.23,y=0.308,source="quest_giver",zoneID=3537},questType="standard"},
[29287] = {id=29287,name="Peaked Interest",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="These fire hawks are beings of fire, but they exhibit much of the same behavior that we've seen in birds back home. It makes me wonder from where they originate. Back to the point - I think we might be able to train them. Domesticate them if you will. Use them against our enemies. I'd like you to retrieve one of their eggs from the top of Fireplume Peak. If you can bring it back to me safely, I will see to the rest.",starts={{npcID=52491,x=0.346,y=0.564,zoneID=5733}},ends={{npcID=52490,x=0.432,y=0.808,zoneID=5733},{npcID=52491,x=0.346,y=0.564,zoneID=5733}},coords={x=0.346,y=0.564,source="quest_giver",zoneID=5733},questType="standard"},
[29290] = {id=29290,name="Fire in the Skies",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="Look at that! It's incredible! Born less than two days ago and already full grown. Sadly, I suspect their life cycle is similarly short, so we'll have to take advantage of any time we have. His training went remarkably well. I want you to be the one to take him out and unleash him on the bulk of the enemy forces gathered near Ragnaros' keep. Show no mercy, .",starts={{npcID=52491,x=0.346,y=0.564,zoneID=5733}},ends={{npcID=52490,x=0.432,y=0.808,zoneID=5733},{npcID=52491,x=0.346,y=0.564,zoneID=5733}},coords={x=0.346,y=0.564,source="quest_giver",zoneID=5733},questType="standard"},
[29293] = {id=29293,name="Singed Wings",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="Many of our Storm Crows have gone ahead to scout the peak and attempt to retrieve some of the fire hawk eggs, but to very little success I'm afraid. The thermals make it nearly impossible to fly safely, and the fire hawks aren't exactly friendly either. I need you to head over there and rescue any druids that you can. I've got splints, bandages, burn salves, smelling salts... anything you'll need to get them back on their feet, assuming they're still alive. Please hurry and help anyone you can find.",starts={{npcID=53259,x=0.344,y=0.564,zoneID=5733}},ends={{npcID=52467,x=0.486,y=0.86,zoneID=5733},{npcID=53259,x=0.344,y=0.564,zoneID=5733}},coords={x=0.344,y=0.564,source="quest_giver",zoneID=5733},questType="standard"},
[29295] = {id=29295,name="The Bigger They Are",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="You're not going to take on fiery behemoths wearing THAT, are you? If you aren't wearing my obsidium crafted goods, you're going to burn right up! And even if you are, you can never have enough of the good stuff. Look , I can craft you the best armor that gold can buy, but I need pure, unsmelted Living Obsidium first. The Obsidium Punishers on Fireplume Peak are literally made of the stuff. Go kill them and gather their pieces.",starts={{npcID=53304,x=0.36,y=0.566,zoneID=5733}},ends={{npcID=53214,x=0.47,y=0.9,zoneID=5733}},coords={x=0.36,y=0.566,source="quest_giver",zoneID=5733},questType="standard"},
[29296] = {id=29296,name="Territorial Birds",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="The fire hawks are upset by our continued presence. They're getting extremely hostile, and not just in the usual territorial ways. I worry that if we leave them unchecked, they will soon be joining the assault on our tree, and I'm not sure we're capable of handling that. Go across the way to Fireplume Peak and do what you have to to keep them in check. I'm far more concerned with our safety right now than theirs, so be decisive about it.",starts={{npcID=53259,x=0.344,y=0.564,zoneID=5733}},ends={{npcID=52467,x=0.486,y=0.86,zoneID=5733},{npcID=53259,x=0.344,y=0.564,zoneID=5733}},coords={x=0.344,y=0.564,source="quest_giver",zoneID=5733},questType="standard"},
[29297] = {id=29297,name="Bye Bye Burdy",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="Staghelm's druids are putting up a fierce fight at Wildflame Point to the northeast. The druids fly above us in fire crow form, then strike when we least expect it. Worst part is, they know exactly how to stay out of our reach! We would be totally helpless, except Damek lent me his trusty harpoon. He says these weapons will fly straight and true even in this super dense air. Take the dwarf's weapon and shoot some birds out of the sky!",starts={{npcID=54163,x=0.662,y=0.654,zoneID=5733}},ends={{npcID=53214,x=0.47,y=0.9,zoneID=5733}},coords={x=0.662,y=0.654,source="quest_giver",zoneID=5733},questType="standard"},
[29298] = {id=29298,name="A Smoke-Stained Locket",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=493,description="This locket has a few small leaf-shaped carvings etched into its face, but any other details have been rubbed away with time, or burned away with fire. It appears to be druidic in nature. Most druids pass through Moonglade during their training. If anybody can help you decipher where this locket came from, it would be Rabine Saturna of Nighthaven.",ends={{npcID=11801,x=0.516,y=0.448,zoneID=493}},questType="standard"},
[29299] = {id=29299,name="Some Like It Hot",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="I've been making progress in my research, . Based on what we've witnessed in the local flora, it's quite possible that your Lasher also accepts superheated liquids as a principal source of nutrition. I'd like you to help me with a little experiment. The Emberspit Scorpions that inhabit the Magma Springs to the north spew out burning pools of fire during combat. Take the Lasher and observe his reaction to the scorpions' Ember Pools.",starts={{npcID=52489,x=0.506,y=0.87,zoneID=5733}},ends={{npcID=52489,x=0.506,y=0.87,zoneID=5733}},coords={x=0.506,y=0.87,source="quest_giver",zoneID=5733},questType="standard"},
[29302] = {id=29302,name="Unlocking the Secrets Within",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=493,description="The initials seem to have worn off of this locket, but I can sense a power within it that suggests only one possible owner: Leyara, the Druid of the Flame. Stand back, and we shall see what surprises this locket contains.",starts={{npcID=11801,x=0.516,y=0.448,zoneID=493}},ends={{npcID=11801,x=0.516,y=0.448,zoneID=493}},coords={x=0.516,y=0.448,source="quest_giver",zoneID=493},questType="standard"},
[29303] = {id=29303,name="Tragedy and Family",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=493,description="You were insightful to bring this locket to me, . I am among the few who know where Valstann's body lays. You can find his resting site in a small graveyard, southeast of Astranaar, in Ashenvale. Bring this locket to the site, and it may unlock more memories. Farewell, , and good luck on your journey.",starts={{npcID=11801,x=0.516,y=0.448,zoneID=493}},coords={x=0.516,y=0.448,source="quest_giver",zoneID=493},questType="standard"},
[29304] = {id=29304,name="The Dogs of War",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="Our forces are falling beneath an unleashed monstrosity - Charhounds from the molten depths. These dogs fear nothing and will not stop until their lust for blood is satisfied. Our forces are barely holding them back. Go join the defenders in the Ashen Fields or in the Molten Flow. Perhaps you can make a dent in their numbers.",starts={{npcID=52824,x=0.458,y=0.858,zoneID=5733}},ends={{npcID=52824,x=0.458,y=0.858,zoneID=5733}},coords={x=0.458,y=0.858,source="quest_giver",zoneID=5733},questType="standard"},
[29305] = {id=29305,name="Strike at the Heart",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="One of Ragnaros' Lieutenants has shown himself at Ragnaros' Reach, the walled area to our northeast. I hoped to send you as soon as you returned, but I suspect Witherbranch and some of our forces have already joined the fight by now. You should hurry. You should be able to drop down the cliff wall right here and reach them quickly.",starts={{npcID=52490,x=0.432,y=0.808,zoneID=5733},{npcID=52492,x=0.36,y=0.566,zoneID=5733}},ends={{npcID=52490,x=0.432,y=0.808,zoneID=5733}},coords={x=0.432,y=0.808,source="quest_giver",zoneID=5733},questType="standard"},
[29307] = {id=29307,name="Heart of Flame",level=35,requiredLevel=35,faction="alliance",expansion=3,zoneID=1519,description="You are the first mortal to witness a dragon council, , and among the only beings in Azeroth to take part in the choosing of an Aspect. My ascension has endowed me with incredible power. I have taken the liberty to strengthen Tarecgosa's bond with you, though she will require a more... permanent home. I would have you venture one last time into the Plane of Fire and bring me the heart of Ragnaros. When next we meet, I will be able to suitably thank you for all that you have done.",starts={{npcID=53349,x=0.232,y=0.228,zoneID=3537}},ends={{npcID=53466,x=0.546,y=0.56,zoneID=1519}},coords={x=0.232,y=0.228,source="quest_giver",zoneID=3537},questType="raid"},
[29308] = {id=29308,name="Heart of Flame",level=35,requiredLevel=35,faction="horde",expansion=3,zoneID=1637,description="You are the first mortal to witness a dragon council, , and among the only beings in Azeroth to take part in the choosing of an Aspect. My ascension has endowed me with incredible power. I have taken the liberty to strengthen Tarecgosa's bond with you, though she will require a more... permanent home. I would have you venture one last time into the Plane of Fire and bring me the heart of Ragnaros. When next we meet, I will be able to suitably thank you for all that you have done.",starts={{npcID=53349,x=0.232,y=0.228,zoneID=3537}},ends={{npcID=53371,x=0.488,y=0.704,zoneID=1637}},coords={x=0.232,y=0.228,source="quest_giver",zoneID=3537},questType="raid"},
[29309] = {id=29309,name="The Stuff of Legends",level=35,requiredLevel=35,faction="horde",expansion=3,zoneID=1519,description="It is an honor to make your acquaintance, . Your deeds echo in the ears of Azeroth's creatures, mortal and immortal alike. I shall present the heart of Ragnaros to Kalecgos when he arrives. Its power is to be harnessed to further endow your weapon. The ceremony is to begin shortly. I have been appointed to escort you there when you are ready.",starts={{npcID=53371,x=0.488,y=0.704,zoneID=1637}},ends={{npcID=53422,x=0.484,y=0.716,zoneID=1637},{npcID=53422,x=0.568,y=0.588,zoneID=1519}},coords={x=0.488,y=0.704,source="quest_giver",zoneID=1637},questType="standard"},
[29310] = {id=29310,name="The Tipping Point",level=32,requiredLevel=32,faction="none",expansion=3,description="On the day when Leyara attacked Hamuul, she was waiting near some ruins in Hyjal, northwest of the Regrowth. She acted strangely at the time: calm, silent, and staring off into the distance. Perhaps that location is of some importance to her. The locket might react if brought to that location.",questType="standard"},
[29311] = {id=29311,name="The Rest is History",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=5733,description="In her memories, Leyara spoke of Malfurion. The tragedies of her past - at least, in her opinion - are largely due to his actions. Malfurion must remember Leyara from before she became a Druid of the Flame. You resolve to bring the locket to him in the Firelands. Hopefully he can answer any remaining questions.",ends={{npcID=52135,x=0.47,y=0.91,zoneID=5733}},questType="standard"},
[29312] = {id=29312,name="The Stuff of Legends",level=35,requiredLevel=35,faction="alliance",expansion=3,zoneID=1637,description="It is an honor to make your acquaintance, . Your deeds echo in the ears of Azeroth's creatures, mortal and immortal alike. I shall present the heart of Ragnaros to Kalecgos when he arrives. Its power is to be harnessed to further endow your weapon. The ceremony is to begin shortly. I have been appointed to escort you there when you are ready.",starts={{npcID=53466,x=0.546,y=0.56,zoneID=1519}},ends={{npcID=53422,x=0.568,y=0.588,zoneID=1519},{npcID=53422,x=0.484,y=0.716,zoneID=1637}},coords={x=0.546,y=0.56,source="quest_giver",zoneID=1519},questType="standard"},
[29313] = {id=29313,name="The Secret to Perfect Kimchi",level=10,requiredLevel=10,faction="alliance",expansion=3,zoneID=1657,description="My family has been making the best kimchi in Darnassus since the city was founded, . The secret is something simple, but it makes all the difference. We bury the jars in the ground until it's ready to serve and my latest batch has just reached that point. You can find the jars buried in earthen mounds all over the city. Would you help me gather them while the contents are just right?",starts={{npcID=4210,x=0.5,y=0.366,zoneID=1657}},ends={{npcID=4210,x=0.5,y=0.366,zoneID=1657}},coords={x=0.5,y=0.366,source="quest_giver",zoneID=1657},questType="standard"},
[29314] = {id=29314,name="Remembering the Ancestors",level=10,requiredLevel=10,faction="alliance",expansion=3,zoneID=1657,description="The living are not the only ones who require sustenance. One of my duties is to prepare the rice cakes that are left for the ancestors. Normally, my senior apprentice has the honor of taking the cakes to the Temple of the Moon for blessing and then presenting them to the ancestors. Since she is out of the city today, would you mind performing the duty in her place?",starts={{npcID=4210,x=0.5,y=0.366,zoneID=1657}},ends={{npcID=208825,x=0.692,y=0.4,zoneID=1657}},coords={x=0.5,y=0.366,source="quest_giver",zoneID=1657},questType="standard"},
[29315] = {id=29315,name="Fungus Among Us",level=10,requiredLevel=10,faction="horde",expansion=3,zoneID=1497,description="Some chefs complain that our beloved Undercity doesn't boast the ingredients to create truly fine fare. Such mewling little cretins. Delicious delights abound! Gather some of the rank, slimy Sewer Caps growing in Undercity's northwest sewer line and return them to me.",starts={{npcID=4552,x=0.622,y=0.446,zoneID=1497}},ends={{npcID=4552,x=0.622,y=0.446,zoneID=1497}},coords={x=0.622,y=0.446,source="quest_giver",zoneID=1497},questType="standard"},
[29316] = {id=29316,name="Back to Basics",level=10,requiredLevel=10,faction="alliance",expansion=3,zoneID=1657,description="There are certain things that everyone needs, from the basic household cook to the master chef. One of the city's most important staples is rice flour. Most families keep at least one basket of rice in their houses and the residents of the Craftsmen's Terrace and Tradesmen's Terrace are no different. I often ask my students to help with the task of pounding rice into flour since it's good practice and an endless task. Why don't you give it a try?",starts={{npcID=4210,x=0.5,y=0.366,zoneID=1657}},ends={{npcID=4210,x=0.5,y=0.366,zoneID=1657}},coords={x=0.5,y=0.366,source="quest_giver",zoneID=1657},questType="standard"},
[29317] = {id=29317,name="Fish Head",level=10,requiredLevel=10,faction="horde",expansion=3,zoneID=1497,description="There was an... incident... with an orc guard and one of Master Apothecary Faranell 's abominations. Apparently, the Kor'kron Overseer chopped its head clean off and kicked it into the slime. Faranell's apprentices searched for hours but they can't find the thing. Care to try fishing it up? I'm sure the old fellow'd be grateful.",starts={{npcID=4573,x=0.81,y=0.312,zoneID=1497}},ends={{npcID=2055,x=0.484,y=0.694,zoneID=1497}},coords={x=0.81,y=0.312,source="quest_giver",zoneID=1497},questType="standard"},
[29318] = {id=29318,name="Ribs for the Sentinels",level=10,requiredLevel=10,faction="alliance",expansion=3,zoneID=1657,description="One of my responsibilities is to feed the sentinels of Darnassus while they're on duty. It's a time-consuming task, but one I'm happy to undertake. It's also a great way to practice your skills. Would you mind helping me with today's meal? Simply take these ribs, cook them near a stove or fire, and distribute them to sentinels throughout the city.",starts={{npcID=4210,x=0.5,y=0.366,zoneID=1657}},ends={{npcID=4210,x=0.5,y=0.366,zoneID=1657}},coords={x=0.5,y=0.366,source="quest_giver",zoneID=1657},questType="standard"},
[29319] = {id=29319,name="Tadpole Terror",level=10,requiredLevel=10,faction="horde",expansion=3,zoneID=1497,description="Some of our apothecaries took to dumping their more volatile waste chemicals into Stillwater Pond and... well, let's just say that no one wants to know how big mutant flesh-eating toads can grow. Would you consider fishing up some giant flesh-eating tadpoles before it gets to that? Just don't try to handle them with your bare hands.",starts={{npcID=4573,x=0.81,y=0.312,zoneID=1497}},ends={{npcID=4573,x=0.81,y=0.312,zoneID=1497}},coords={x=0.81,y=0.312,source="quest_giver",zoneID=1497},questType="standard"},
[29320] = {id=29320,name="Like Pike?",level=10,requiredLevel=10,faction="horde",expansion=3,zoneID=1497,description="You've fished in Brightwater Lake, yes? The prize catch there is one of the lake's massive corpse-fed pikes . However, they only bite on a very specific type of bait... corpse worms . Search the graves in the courtyard up top and you should find some.",starts={{npcID=4573,x=0.81,y=0.312,zoneID=1497}},ends={{npcID=4573,x=0.81,y=0.312,zoneID=1497}},coords={x=0.81,y=0.312,source="quest_giver",zoneID=1497},questType="standard"},
[29321] = {id=29321,name="Happy as a Clam Digger",level=10,requiredLevel=10,faction="alliance",expansion=3,zoneID=1657,description="It seems like everyone I know loves clams, but I can't stand them! They're smelly and slimy, and harvesting them means digging through mud. Give me a fishing pole and some bait any day. Still, I want to surprise my brother with a bucket of fresh clams. I'd reward you if you were willing to gather those clams for me. Just go through the portal to Rut'theran Village and look for the clams in the shallows near the shore.",starts={{npcID=4156,x=0.49,y=0.61,zoneID=1657}},ends={{npcID=4156,x=0.49,y=0.61,zoneID=1657}},coords={x=0.49,y=0.61,source="quest_giver",zoneID=1657},questType="standard"},
[29322] = {id=29322,name="Time for Slime",level=10,requiredLevel=10,faction="horde",expansion=3,zoneID=1497,description="It takes a special sort of fisherman to reap the bounty of Undercity's burbling slime troughs. Think you can handle gathering some of the squirming, sentient slime mold slithering about down there? You can try to fish them up, but they're wily; you might be better off just diving into the ooze and grabbing them. Remember, they're only useful alive and intact... who'd want to eat a dead slime mold?! Disgusting.",starts={{npcID=4573,x=0.81,y=0.312,zoneID=1497}},ends={{npcID=4573,x=0.81,y=0.312,zoneID=1497}},coords={x=0.81,y=0.312,source="quest_giver",zoneID=1497},questType="standard"},
[29323] = {id=29323,name="Stocking Up",level=10,requiredLevel=10,faction="alliance",expansion=3,zoneID=1657,description="We've used up most of our food stores in taking care of refugees and feeding those whose homes and livelihoods were destroyed. If we don't replenish our stores, we'll all be in danger next time there's a bad storm or a Horde invasion. Perhaps you'd be willing to help me build up our stock of lake whitefish . You can catch it anywhere in Darnassus, and once it's dried, it'll keep until it's needed.",starts={{npcID=4156,x=0.49,y=0.61,zoneID=1657}},ends={{npcID=4156,x=0.49,y=0.61,zoneID=1657}},coords={x=0.49,y=0.61,source="quest_giver",zoneID=1657},questType="standard"},
[29324] = {id=29324,name="The Sister's Pendant",level=10,requiredLevel=10,faction="alliance",expansion=3,zoneID=1657,description="Have you met Sister Aquinne? She and I trained together in Dolanaar, and she recently came to the city to study at the Temple of the Moon. We decided to go for a boat ride, but the clumsy oarsman managed to capsize the craft! When we got back to the shore, Aquinne's moon pendant was missing. The lakes in Darnassus are full of giant catfish who will gobble up anything shiny! I've been catching them nonstop, hoping to find the one with her pendant. I don't suppose you want to help?",starts={{npcID=4156,x=0.49,y=0.61,zoneID=1657}},ends={{npcID=4156,x=0.49,y=0.61,zoneID=1657}},coords={x=0.49,y=0.61,source="quest_giver",zoneID=1657},questType="standard"},
[29325] = {id=29325,name="A Slippery Snack",level=10,requiredLevel=10,faction="alliance",expansion=3,zoneID=1657,description="Have you ever eaten octopus meat? It takes some getting used to, but it's my favorite! I even know some people who like to eat the whole thing while it's alive! I don't plan on trying that anytime soon, but I am out of fresh octopi at the moment. Will you help me gather some more? They live in the shallow water off the shore near Rut'theran Village.",starts={{npcID=4156,x=0.49,y=0.61,zoneID=1657}},ends={{npcID=4156,x=0.49,y=0.61,zoneID=1657}},coords={x=0.49,y=0.61,source="quest_giver",zoneID=1657},questType="standard"},
[29326] = {id=29326,name="The Nordrassil Summit",level=35,requiredLevel=35,faction="both",expansion=3,zoneID=616,description="Hello, ! My brothers and sisters of the Earthen Ring have spoken well of your deeds in the wake of the Cataclysm. But much remains to be done if we are to heal this broken world. Walk with me, friend. Preparations for a ceremony are underway, a ritual that I hope will be a turning point in our battle against the Twilight's Hammer. When all is done, you will be able to spread the word about our triumph here.",starts={{npcID=54313,x=0.606,y=0.314,zoneID=616}},ends={{npcID=54312,x=0.602,y=0.302,zoneID=616}},coords={x=0.606,y=0.314,source="quest_giver",zoneID=616},questType="standard"},
[29327] = {id=29327,name="Elemental Bonds: Doubt",level=35,requiredLevel=35,faction="both",expansion=3,zoneID=5034,description="I do know the one you seek... but I do not know if it is wise for you to follow him. He has cast himself into the cyclone. The winds now tear at his body and mind, leaving nothing but shreds of flesh and doubt. Chasing after him would only expose you to the same fate. The wind's edge leaves nothing uncut. You have been warned. Now what will you do?",starts={{npcID=53524,x=0.476,y=0.886,zoneID=5034}},ends={{npcID=53519,x=0.342,y=0.776,zoneID=5034}},coords={x=0.476,y=0.886,source="quest_giver",zoneID=5034},questType="standard"},
[29328] = {id=29328,name="Elemental Bonds: Desire",level=35,requiredLevel=35,faction="both",expansion=3,zoneID=5145,description="Once again, , I cannot do this without your help. I will try to quiet this tempest, but you will need to fight back the unstable elementals that whirl around it. Only then can we free Go'el!",starts={{npcID=53652,x=0.698,y=0.342,zoneID=5145}},ends={{npcID=53652,x=0.698,y=0.342,zoneID=5145}},coords={x=0.698,y=0.342,source="quest_giver",zoneID=5145},questType="standard"},
[29329] = {id=29329,name="Elemental Bonds: Patience",level=35,requiredLevel=35,faction="both",expansion=3,zoneID=5042,description="With the Stonemother's blessing, I can take us to where Go'el is being held. We must be careful. The Twilight's Hammer has agents all around. You help me hold them off while I attempt to get through to Go'el! Speak with me when you are ready, and I will take you to him.",starts={{npcID=53738,x=0.64,y=0.46,zoneID=5042}},ends={{npcID=53738,x=0.64,y=0.46,zoneID=5042}},coords={x=0.64,y=0.46,source="quest_giver",zoneID=5042},questType="standard"},
[29330] = {id=29330,name="Elemental Bonds: Fury",level=35,requiredLevel=35,faction="both",expansion=3,zoneID=5733,description="The totems, ! We need to activate them, or Go'el is lost! Kill the elementals next to each of my totems, located around the edges of this plateau. Once all four totems are activated, we should be able to free the last piece of Go'el's soul!",starts={{npcID=53925,x=0.512,y=0.258,zoneID=5733}},coords={x=0.512,y=0.258,source="quest_giver",zoneID=5733},questType="standard"},
[29331] = {id=29331,name="Elemental Bonds: The Vow",level=35,requiredLevel=35,faction="both",expansion=3,zoneID=616,description="Before he passed through the portal to Mount Hyjal, Thrall asked you to follow him. There is something he would like you to witness.",ends={{npcID=54168,x=0.602,y=0.298,zoneID=616}},questType="standard"},
[29332] = {id=29332,name="Lily, Oh Lily",level=10,requiredLevel=10,faction="horde",expansion=3,zoneID=1497,description="The lilies that grow around Stillwater Pond can be rendered down into a delightful broth. Well... by \"delightful,\" I mean \"won't immediately sicken any orc who drinks it.\" Why don't you go gather some for me, hmmm? Just watch out for the giant flesh-eating tadpoles.",starts={{npcID=4552,x=0.622,y=0.446,zoneID=1497}},ends={{npcID=4552,x=0.622,y=0.446,zoneID=1497}},coords={x=0.622,y=0.446,source="quest_giver",zoneID=1497},questType="standard"},
[29333] = {id=29333,name="Escargot A Go-Go",level=10,requiredLevel=10,faction="horde",expansion=3,zoneID=1497,description="The orc guards are always grumbling about bland and moldering Undercity fare - as if it's OUR fault they can't get by on a diet of mushrooms and old corpses - so I think it's time they learn just the sort of exotic delights we can cook up when we've a mind to. Gather some of the freshwater snails ambling about beneath Brightwater Lake and I'll show them what a true culinary master can create.",starts={{npcID=4552,x=0.622,y=0.446,zoneID=1497}},ends={{npcID=4552,x=0.622,y=0.446,zoneID=1497}},coords={x=0.622,y=0.446,source="quest_giver",zoneID=1497},questType="standard"},
[29334] = {id=29334,name="Roach Coach",level=10,requiredLevel=10,faction="horde",expansion=3,zoneID=1497,description="For all the grousing those Kor'kron Overseers do about Undercity food, there's ONE thing they'll eat in spades: My sister Audrey's Thrice-Spiced Crunchy Stew. Its popularity means she's always running low on ingredients. Could you gather some for her at the coach she sells them from? You'll find traps all over the city; just take their contents to Audrey and she'll handle the rest!",starts={{npcID=4552,x=0.622,y=0.446,zoneID=1497}},ends={{npcID=53528,x=0.624,y=0.354,zoneID=1497}},coords={x=0.622,y=0.446,source="quest_giver",zoneID=1497},questType="standard"},
[29335] = {id=29335,name="Into Slashing Winds",level=35,requiredLevel=35,faction="both",expansion=3,zoneID=5034,description=", I refuse to believe my Go'el is lost forever. His spirit has been scattered across the elemental planes. If even a part of him still exists, we can find him, but I will need your help. We will start with the plane of air. Speak to me and we will travel to the Vortex Pinnacle together. We must speak with an elemental, Cyclonas . He's capricious, but he sees everything in the realm of air. If my love is there, Cyclonas will know what's become of him.",starts={{npcID=54312,x=0.602,y=0.302,zoneID=616}},ends={{npcID=53524,x=0.476,y=0.886,zoneID=5034}},coords={x=0.602,y=0.302,source="quest_giver",zoneID=616},questType="standard"},
[29336] = {id=29336,name="Into Coaxing Tides",level=35,requiredLevel=35,faction="both",expansion=3,zoneID=5145,description="Go'el must be in the plane of water... the Abyssal Maw itself! I shudder to imagine what fate awaits him there. Find the elemental, Hydrius , near the Abyssal Breach. He knows of Go'el and is sympathetic to our fight against Ragnaros. If anyone can help you there, it's him. I will meet you beneath the tides of Vashj'ir, ...",starts={{npcID=53519,x=0.342,y=0.776,zoneID=5034}},ends={{npcID=53677,x=0.696,y=0.344,zoneID=5145}},coords={x=0.342,y=0.776,source="quest_giver",zoneID=5034},questType="standard"},
[29337] = {id=29337,name="Into Constant Earth",level=35,requiredLevel=35,faction="both",expansion=3,zoneID=5042,description="Time is short! My love lies in Deepholm. I will take us there when you are ready, and we will speak with Therazane the Stonemother.",starts={{npcID=53652,x=0.698,y=0.342,zoneID=5145}},ends={{npcID=42465,x=0.564,y=0.122,zoneID=5042}},coords={x=0.698,y=0.342,source="quest_giver",zoneID=5145},questType="standard"},
[29338] = {id=29338,name="Into Unrelenting Flame",level=35,requiredLevel=35,faction="both",expansion=3,zoneID=5733,description="We must travel now to the Firelands. Within that realm, Go'el's burning spirit could become as terrible as Ragnaros himself! Prepare yourself, for we will be alone in a hostile world. Speak with me when you are ready... and may the ancestors protect us!",starts={{npcID=53738,x=0.64,y=0.46,zoneID=5042}},ends={{npcID=54014,x=0.498,y=0.32,zoneID=5733}},coords={x=0.64,y=0.46,source="quest_giver",zoneID=5042},questType="standard"},
[29339] = {id=29339,name="Short-Supply Reward",level=35,requiredLevel=35,faction="none",expansion=3,questType="standard"},
[29342] = {id=29342,name="Cold Water Fishing",level=10,requiredLevel=10,faction="alliance",expansion=3,zoneID=1537,description="The best tastin' fish live in the cold waters o' Dun Morogh, , an' don't let anyone else tell ye otherwise! Me favorite, an' the most popular one in Ironforge, is the arctic char , which only comes from our ancestral lands. I like tae think o' it as Ironforge's gift t' the world! Why don't ye try yer hand at catchin' a few yerself? The best place tae find 'em is down in Helm's Bed Lake, in the eastern end o' Dun Morogh.",starts={{npcID=5161,x=0.484,y=0.082,zoneID=1537}},ends={{npcID=5161,x=0.484,y=0.082,zoneID=1537}},coords={x=0.484,y=0.082,source="quest_giver",zoneID=1537},questType="standard"},
[29343] = {id=29343,name="One fer the Ages",level=10,requiredLevel=10,faction="alliance",expansion=3,zoneID=1537,description="I'm sure by now ye've heard the tale o' Old Ironjaw, the most famous and elusive fish in the waters o' Ironforge's Forlorn Cavern. Well, in his many years, he's been responsible for the rise o' many young ironjaws . Don't let the name fool ye, , these young'uns are every bit as clever as their dad, but somewhat lackin' in experience. With skill an' patience, ye could probably catch one, an' when ye do, bring it to the museum in Ironforge's Library an' put it on display fer all to see!",starts={{npcID=5161,x=0.484,y=0.082,zoneID=1537}},ends={{npcID=5161,x=0.484,y=0.082,zoneID=1537}},coords={x=0.484,y=0.082,source="quest_giver",zoneID=1537},questType="standard"},
[29344] = {id=29344,name="Fish fer Squrky",level=10,requiredLevel=10,faction="alliance",expansion=3,zoneID=1537,description="Hae I introduced ye tae me pet, Squrky? I'm teachin' him tae fish all proper-like. Fer now, I've been feedin' him minnows fished from the pool in this cavern. Maybe ye'd like tae give it a try? Just cast yer lure in the pool over there and feed Squrky any minnows ye happen tae fish up. He'll love ye ferever!",starts={{npcID=5161,x=0.484,y=0.082,zoneID=1537}},ends={{npcID=5161,x=0.484,y=0.082,zoneID=1537}},coords={x=0.484,y=0.082,source="quest_giver",zoneID=1537},questType="standard"},
[29345] = {id=29345,name="Pond Predators",level=10,requiredLevel=10,faction="horde",expansion=3,zoneID=1638,description="A well-meaning goblin visitor introduced Azshara snakeheads to our waters and now they're overrunning the pond. Please, if you can catch some of these voracious predatory fish before they eat every smallfish and mud snapper in Thunder Bluff, I'd be terribly grateful.",starts={{npcID=3028,x=0.56,y=0.47,zoneID=1638}},ends={{npcID=3028,x=0.56,y=0.47,zoneID=1638}},coords={x=0.56,y=0.47,source="quest_giver",zoneID=1638},questType="standard"},
[29346] = {id=29346,name="The Ring's the Thing",level=10,requiredLevel=10,faction="horde",expansion=3,zoneID=1638,description="One of the Forsaken from the Pools of Vision came to me and said he'd lost his ring to a blind cavefish in the waters there. Or perhaps it was his finger. It was hard to tell; his jaw did not move and his Orcish was no better than mine. In any case, I thought it would be a kind gesture towards our unusual visitors to catch and gut cavefish until the ring - or finger - was found. Would you help?",starts={{npcID=3028,x=0.56,y=0.47,zoneID=1638}},ends={{npcID=30709,x=0.288,y=0.204,zoneID=1638}},coords={x=0.56,y=0.47,source="quest_giver",zoneID=1638},questType="standard"},
[29347] = {id=29347,name="Live Bait",level=10,requiredLevel=10,faction="alliance",expansion=3,zoneID=1,description="If ye've ever fished fer crayfish, ye know they respond best to live bait, an' the more bait, the better. Would ye like to test my new bait? Simply smear this on yerself an' hop into Helm's Bed Lake in eastern Dun Morogh. After ye've got the catch, take it to me friend, Cook Ghilm at Gol'Bolar Quarry, west of the lake. He's an expert at cookin' those oversized bugs!",starts={{npcID=5161,x=0.484,y=0.082,zoneID=1537}},ends={{npcID=1355,x=0.756,y=0.528,zoneID=1}},coords={x=0.484,y=0.082,source="quest_giver",zoneID=1537},questType="standard"},
[29348] = {id=29348,name="The Race to Restock",level=10,requiredLevel=10,faction="horde",expansion=3,zoneID=1638,description="Thunder Bluff's fishing pond is being overrun with voracious Azshara snakeheads; there are hardly any smallfish or mud snappers left. We already have fishers trying to kill as many snakeheads as they can, but can you assist us in our restocking efforts? If you could gather some fish from Stonebull Lake and bring them here to Thunder Bluff, I would be very grateful.",starts={{npcID=3028,x=0.56,y=0.47,zoneID=1638}},ends={{npcID=3028,x=0.56,y=0.47,zoneID=1638}},coords={x=0.56,y=0.47,source="quest_giver",zoneID=1638},questType="standard"},
[29349] = {id=29349,name="Craving Crayfish",level=10,requiredLevel=10,faction="horde",expansion=3,zoneID=1638,description="One of the great delicacies of Mulgore is the crayfish that dwell in our lakes and streams. They are particularly popular during weddings or the celebration of a birth. Would you help me catch some of these crafty crustaceans for the cooking pots of Thunder Bluff? You can fish them up from Stonebull Lake, or simply dive in and grab them.",starts={{npcID=3028,x=0.56,y=0.47,zoneID=1638}},ends={{npcID=3028,x=0.56,y=0.47,zoneID=1638}},coords={x=0.56,y=0.47,source="quest_giver",zoneID=1638},questType="standard"},
[29350] = {id=29350,name="The Gnomish Bait-o-Matic",level=10,requiredLevel=10,faction="alliance",expansion=3,zoneID=1537,description="One o' the gnomish engineerin' trainers gave me a blueprint fer a fancy lure he says'll help me catch fish faster and keep 'em from gettin' away. The whole thing sounds a mite silly if ye ask me, but I'll try anythin' once. Here are the blueprints. Ye're going to need shiny baubles, which ye can buy from my assistant inside the buildin', a hair trigger ye can buy from an engineerin' supplier in Tinker Town, and a few rat traps from the Deeprun Tram.",starts={{npcID=5161,x=0.484,y=0.082,zoneID=1537}},ends={{npcID=5161,x=0.484,y=0.082,zoneID=1537}},coords={x=0.484,y=0.082,source="quest_giver",zoneID=1537},questType="standard"},
[29351] = {id=29351,name="A Round for the Guards",level=10,requiredLevel=10,faction="alliance",expansion=3,zoneID=1537,description="The guards who defend Ironforge put their lives on the line against our many enemies, and it's up to us to take care of them. Today, their rations consist of two dwarven favorites, haggis and Ironforge pale ale. Would ye be so kind as to help me distribute them? That way, everyone gets his food in a timely manner and we can move on to other tasks.",starts={{npcID=5159,x=0.601,y=0.364,zoneID=1537}},ends={{npcID=5159,x=0.601,y=0.364,zoneID=1537}},coords={x=0.601,y=0.364,source="quest_giver",zoneID=1537},questType="standard"},
[29352] = {id=29352,name="A Fowl Shortage",level=10,requiredLevel=10,faction="alliance",expansion=3,zoneID=1537,description="Oh, no, , this is going to be a disaster if we don't find some chicken soon... Ye just cannae make cock-a-leekie soup without the chicken! It's not possible! There's still time to make the soup and broth if ye can find some fresh chicken. Will ye help me? There are usually a few chickens running around outside the front entrance to the city. If ye can get yer hands on, say, six o' them, that should save me soup.",starts={{npcID=5159,x=0.601,y=0.364,zoneID=1537}},ends={{npcID=5159,x=0.601,y=0.364,zoneID=1537}},coords={x=0.601,y=0.364,source="quest_giver",zoneID=1537},questType="standard"},
[29353] = {id=29353,name="Keepin' the Haggis Flowin'",level=10,requiredLevel=10,faction="alliance",expansion=3,zoneID=1537,description="The haggis must flow. Aye, it's a figure o' speech, for haggis'll ne'er flow! Ye dinnae want to know what'll happen if the people o' Ironforge don't get their haggis. I'm working on the next batch, but I'm still missing a couple of ingredients. Sognar Cliffbeard is the meat vendor in the Military Ward, an' he'll sell you the big bag o' sheep innards I need. Ye can buy mild spices from any cooking supplier and ye can find sacks o' oatmeal in any inn or among the supplies in the city.",starts={{npcID=5159,x=0.601,y=0.364,zoneID=1537}},ends={{npcID=5159,x=0.601,y=0.364,zoneID=1537}},coords={x=0.601,y=0.364,source="quest_giver",zoneID=1537},questType="standard"},
[29354] = {id=29354,name="Shiny Baubles",level=10,requiredLevel=10,faction="horde",expansion=3,zoneID=1638,description="One of a fisher's most simple and effective tools is the shiny bauble; affixed to a line, even the most novice angler has a chance at a catch. With all the fishing going on of late, though, Thunder Bluff is in woefully short supply! Might I ask you to collect shiny stones from around the base of the central rise? Bring them to Nahari Cloudchaser so that she might craft more shiny baubles with them.",starts={{npcID=3028,x=0.56,y=0.47,zoneID=1638}},ends={{npcID=52657,x=0.35,y=0.538,zoneID=1638}},coords={x=0.56,y=0.47,source="quest_giver",zoneID=1638},questType="standard"},
[29355] = {id=29355,name="Can't Get Enough Spice Bread",level=10,requiredLevel=10,faction="alliance",expansion=3,zoneID=1537,description="It might seem like a basic thing, , but spice bread is a longtime favorite in Ironforge. Some days, I have trouble keeping up! Would ye like to cook some to practice yer skills an' help meet the demand? Ye can buy all the ingredients ye'll need from me brother, Emrul Riknussun, who is downstairs.",starts={{npcID=5159,x=0.601,y=0.364,zoneID=1537}},ends={{npcID=5159,x=0.601,y=0.364,zoneID=1537}},coords={x=0.601,y=0.364,source="quest_giver",zoneID=1537},questType="standard"},
[29356] = {id=29356,name="I Need to Cask a Favor",level=10,requiredLevel=10,faction="alliance",expansion=3,zoneID=1537,description="My stocks o' IPA, that's Ironforge Pale Ale for ye novices, are gettin' low. Luckily, the brewery isn't too far away an' they should have a new cask o' Drugan's IPA waitin' fer us. That Drugan's a genius of a brewer, I tell ye. I won't be able to get down to Kharanos meself today, but perhaps ye can dash down there, pick up the new cask an' run it back 'ere? What d'ye say?",starts={{npcID=5159,x=0.601,y=0.364,zoneID=1537}},ends={{npcID=5159,x=0.601,y=0.364,zoneID=1537}},coords={x=0.601,y=0.364,source="quest_giver",zoneID=1537},questType="standard"},
[29357] = {id=29357,name="Spice Bread Aplenty",level=10,requiredLevel=10,faction="alliance",expansion=3,zoneID=1657,description="Isn't it amazing how something as simple as spice bread is used every day in Darnassus? When I'm not seeing to my other responsibilities, I like to bake spice bread to hone my skills as a cook and practice my technique. Why don't you give it a try? You should be able to get your ingredients here in the shop. No matter how much we make, it never goes to waste. Bring me your loaves when you're done and I'll have someone share them with our friends, the Gilneans.",starts={{npcID=4210,x=0.5,y=0.366,zoneID=1657}},ends={{npcID=4210,x=0.5,y=0.366,zoneID=1657}},coords={x=0.5,y=0.366,source="quest_giver",zoneID=1657},questType="standard"},
[29358] = {id=29358,name="Pining for Nuts",level=10,requiredLevel=10,faction="horde",expansion=3,zoneID=1638,description="The Shu'halo use pine nuts in so MANY dishes: meat, fish, vegetables, even baked into breads or sprinkled over sweet pastries. The Earth Mother has blessed us in that the very BEST pine nuts come from the trees upon these very mesas. Simply gather pine cones and toast them over a cooking fire to release the nuts within. Would you please be so kind as to gather some? There are hardly ever enough to go around...",starts={{npcID=3026,x=0.51,y=0.528,zoneID=1638}},ends={{npcID=3026,x=0.51,y=0.528,zoneID=1638}},coords={x=0.51,y=0.528,source="quest_giver",zoneID=1638},questType="standard"},
[29359] = {id=29359,name="An Old Favorite",level=10,requiredLevel=10,faction="alliance",expansion=3,zoneID=1657,description="Herring is one of the most sought-after fish in Darnassus, but not just any herring. The Kaldorei herring is native only to the waters surrounding Teldrassil. I try to keep a good supply of it because it's so versatile! I just finished smoking a batch of it, so I need to rebuild my stocks. Would you mind helping me? You can catch Kaldorei herring by fishing in Rut'theran Village.",starts={{npcID=4156,x=0.49,y=0.61,zoneID=1657}},ends={{npcID=4156,x=0.49,y=0.61,zoneID=1657}},coords={x=0.49,y=0.61,source="quest_giver",zoneID=1657},questType="standard"},
[29360] = {id=29360,name="Would You Like Some Flies With That?",level=10,requiredLevel=10,faction="horde",expansion=3,zoneID=1497,description="It's not always about making food for the orcs, . This time, it's about making food for what will hopefully be their replacements. We need to start small, we need to catch flies. Flies love rotting meat, and we love rotting meat... as projectile weapons! Check out the Meat Wagons for any extra bits of meat. Where you find the meat, you'll find the flies. Bring me 25 bloated flies, and then I can start on the next stage of our cooking plan.",starts={{npcID=4552,x=0.622,y=0.446,zoneID=1497}},ends={{npcID=4552,x=0.622,y=0.446,zoneID=1497}},coords={x=0.622,y=0.446,source="quest_giver",zoneID=1497},questType="standard"},
[29361] = {id=29361,name="Moat Monster!",level=10,requiredLevel=10,faction="horde",expansion=3,zoneID=1497,description="Sometimes fishing means throwing something back, . We've been overfeeding these frogs for just that occasion. We've fed these frogs bloated spiders, that were fed bloated flies, and now, we are going to feed a real monster. The moat above, in the Ruins of Lordaeron, is home to our very own moat monster. Today is feeding day. But we must train it as well. In this bag, you will find a decoy kit and some bloated frogs . Use the decoy kit, then toss the frogs to the monster when it appears.",starts={{npcID=4573,x=0.81,y=0.312,zoneID=1497}},ends={{npcID=4573,x=0.81,y=0.312,zoneID=1497}},coords={x=0.81,y=0.312,source="quest_giver",zoneID=1497},questType="standard"},
[29362] = {id=29362,name="\"Magic\" Mushrooms",level=10,requiredLevel=10,faction="horde",expansion=3,zoneID=1638,description="You know of the Pools of Vision, yes? There is a sort of mushroom that grows there... not the tough, rank fungi that dominates the place, but smaller, more delicate caps that grow beneath them. They are rare and quite delicious, adding a flavor to meat dishes that one might even call magical. ...what? No, really. They just taste good. That's it.",starts={{npcID=3026,x=0.51,y=0.528,zoneID=1638}},ends={{npcID=3026,x=0.51,y=0.528,zoneID=1638}},coords={x=0.51,y=0.528,source="quest_giver",zoneID=1638},questType="standard"},
[29363] = {id=29363,name="Mulgore Spice Bread",level=10,requiredLevel=10,faction="horde",expansion=3,zoneID=1638,description="I am often asked, \"Aska, who is making all this Mulgore spice bread?!\" It is a reasonable question. Our fine and noble bread is traded in countless settlements in the most far-away lands, even by our staunchest foes. IT'S JUST THAT GOOD. And the answer...? It is \"YOU.\" Please take this packet of Mulgore spices and use it to turn bland, boring spice bread into MULGORE spice bread!",starts={{npcID=3026,x=0.51,y=0.528,zoneID=1638}},ends={{npcID=3026,x=0.51,y=0.528,zoneID=1638}},coords={x=0.51,y=0.528,source="quest_giver",zoneID=1638},questType="standard"},
[29364] = {id=29364,name="Corn Mash",level=10,requiredLevel=10,faction="horde",expansion=3,zoneID=1638,description="One of Thunder Bluff's most important staples is cornmeal; bowls of corn may be found in nearly every home. With so many of the local mills under constant attack by harpies, gnolls, reckless mining companies and Earth Mother knows what else, I often ask my students to help with the task of grinding corn into cornmeal. Would you care to help?",starts={{npcID=3026,x=0.51,y=0.528,zoneID=1638}},ends={{npcID=3026,x=0.51,y=0.528,zoneID=1638}},coords={x=0.51,y=0.528,source="quest_giver",zoneID=1638},questType="standard"},
[29365] = {id=29365,name="Perfectly Picked Portions",level=10,requiredLevel=10,faction="horde",expansion=3,zoneID=1638,description="Even the novice cook knows that a great dish begins with great ingredients. I have standing orders with merchants throughout Thunder Bluff, but I'd like to see how well you do at selecting the very best of what they have to offer. Please make the rounds and gather perfect portions of meat, fish, vegetables and herbs from local merchant stalls.",starts={{npcID=3026,x=0.51,y=0.528,zoneID=1638}},ends={{npcID=3026,x=0.51,y=0.528,zoneID=1638}},coords={x=0.51,y=0.528,source="quest_giver",zoneID=1638},questType="standard"},
[29371] = {id=29371,name="A Time to Lose",level=10,requiredLevel=10,faction="alliance",expansion=3,zoneID=13983,description="Well met, . As we attempt to embrace the Wickerman ceremony, it is no surprise that the Horde would attempt to ruin our celebration. Now the prudent course of action may be to rise above the conflict and simply ignore the attacks. I admire those that take that high road, but I cannot help them. But for those that seek to strike back... I can help them. If you are interested, , take this Dousing Agent and use it on the Horde's Wickerman in the Ruins of Lordaeron.",starts={{npcID=52064,x=0.32,y=0.504,zoneID=12}},ends={{npcID=52064,x=0.32,y=0.504,zoneID=12}},coords={x=0.32,y=0.504,source="quest_giver",zoneID=12},questType="standard"},
[29372] = {id=29372,name="Trouble in Podunk",level=1,requiredLevel=1,faction="both",expansion=3,zoneID=4922,mapID=241,description="Outlaws have kidnapped the sheriff!",questType="standard"},
[29373] = {id=29373,name="Trouble in Podunk",level=1,requiredLevel=1,faction="both",expansion=3,zoneID=4922,mapID=241,description="We never paid no heed to Sheriff Blundy, what with his gettin' all up-in-arms at all times 'bout his \"laws\" and his \"mis-de-meanors.\" But them dirty ol' McClintocks, and their cattle-rustlin' pappy up in Truckshaw ridge done had it up to here with the frequent incarcerations and trials and posse-gatherin' and dead-or-alive-wantin', and come this past week they done took the law into their own hands - in the most literal of senses - by haulin' up and hi-jackin' the good Sheriff. As you can see, our humble",questType="standard"},
[29374] = {id=29374,name="Stink Bombs Away!",level=10,requiredLevel=10,faction="horde",expansion=3,zoneID=1497,description="The foolish Alliance have employed hags to fuel an attack on our city. Well, as my sister once told me, \"Turnabout is fair play.\" We will gladly return the favor. Speak with my sister, and she will provide you with a broomstick flight over Stormwind. While over Stormwind, drop stink bombs on the city and on the people. Make them suffer! We will show those hags in Stormwind who is the most powerful.",starts={{npcID=53763,x=0.624,y=0.668,zoneID=85},{npcID=53763,x=0.686,y=0.08,zoneID=1497}},ends={{npcID=53763,x=0.624,y=0.668,zoneID=85},{npcID=53763,x=0.686,y=0.08,zoneID=1497}},coords={x=0.624,y=0.668,source="quest_giver",zoneID=85},questType="standard"},
[29375] = {id=29375,name="Clean Up in Undercity",level=10,requiredLevel=10,faction="horde",expansion=3,zoneID=1497,description="Greetings, ! Are you enjoying Hallow's End? It seems that in response to our stink bombing Stormwind, the Alliance has decided to stink bomb our city. Fortunately, we have magics that can handle the stink the Alliance bring us. Use this Arcane Cleanser to remove the stink bombs from the city.",starts={{npcID=53763,x=0.624,y=0.668,zoneID=85},{npcID=53763,x=0.686,y=0.08,zoneID=1497}},ends={{npcID=53763,x=0.624,y=0.668,zoneID=85},{npcID=53763,x=0.686,y=0.08,zoneID=1497}},coords={x=0.624,y=0.668,source="quest_giver",zoneID=85},questType="standard"},
[29376] = {id=29376,name="A Time to Build Up",level=10,requiredLevel=10,faction="horde",expansion=3,zoneID=1497,description="We burn the effigy of the Wickerman as a symbol of our struggle against those who would oppose us. We wear the ashes of the burnt Wickerman as a symbol of our neverending fight against those who would enslave us. Use the bonfire nearby and ignite the Wickerman. Then take the ashes that lay nearby and spread them across your face. These gestures will serve as a reminder to our enemies that we shall never yield.",starts={{npcID=15197,x=0.62,y=0.678,zoneID=85},{npcID=15197,x=0.672,y=0.128,zoneID=1497}},ends={{npcID=15197,x=0.62,y=0.678,zoneID=85},{npcID=15197,x=0.672,y=0.128,zoneID=1497}},coords={x=0.62,y=0.678,source="quest_giver",zoneID=85},questType="standard"},
[29377] = {id=29377,name="A Time to Break Down",level=10,requiredLevel=10,faction="horde",expansion=3,zoneID=1497,description="Well met, . As we revel in the Wickerman ceremony, it comes as no surprise that the Alliance would attempt to ruin our celebration. We have an opportunity to make them pay. If you are interested, , take this Dousing Agent and use it on the Alliance's Wickerman in front of Stormwind. Extinguish their flame and revel in their misery, .",starts={{npcID=15197,x=0.62,y=0.678,zoneID=85},{npcID=15197,x=0.672,y=0.128,zoneID=1497}},ends={{npcID=15197,x=0.62,y=0.678,zoneID=85},{npcID=15197,x=0.672,y=0.128,zoneID=1497}},coords={x=0.62,y=0.678,source="quest_giver",zoneID=85},questType="standard"},
[29382] = {id=29382,name="Thanks, But No Thanks",level=1,requiredLevel=1,faction="none",expansion=3,description="A holiday sweater may not be for everyone. The receipt says that you can exchange it for gold at any Smokywood Pastures merchant. All exchanges are final.",questType="standard"},
[29383] = {id=29383,name="Thanks, But No Thanks",level=1,requiredLevel=1,faction="none",expansion=3,description="A holiday sweater may not be for everyone. The receipt says that you can exchange it for gold at any Smokywood Pastures merchant. All exchanges are final.",questType="standard"},
[29385] = {id=29385,name="A Winter Veil Gift",level=10,requiredLevel=10,faction="both",expansion=3,zoneID=1637,mapID=85,starts={{npcID=187236,x=0.335,y=0.66,mapID=87},{npcID=187236,x=0.494,y=0.775,mapID=85}},ends={{npcID=187236,x=0.335,y=0.66,mapID=87},{npcID=187236,x=0.494,y=0.775,mapID=85}},coords={x=0.335,y=0.66,source="quest_giver",mapID=85},questType="standard"},
[29387] = {id=29387,name="Guardians of Hyjal: Firelands Invasion!",level=32,requiredLevel=32,faction="alliance",expansion=3,zoneID=616,description="The Guardians of Hyjal, led by Arch Druid Malfurion Stormrage, seek brave heroes to assist with a full-scale assault on the Firelands. Willing and able-bodied heroes of the Alliance should report to the Sanctuary of Malorne in Mount Hyjal immediately.",starts={{npcID=206111,x=0.629,y=0.717,zoneID=1519},{npcID=206294,x=0.623,y=0.301,zoneID=1519},{npcID=207320,x=0.258,y=0.696,zoneID=1537},{npcID=207320,x=0.414,y=0.448,zoneID=7078},{npcID=207321,x=0.45,y=0.499,zoneID=1657}},ends={{npcID=52669,x=0.272,y=0.624,zoneID=616}},coords={x=0.629,y=0.717,source="quest_giver",zoneID=1519},questType="standard"},
[29388] = {id=29388,name="Guardians of Hyjal: Firelands Invasion!",level=32,requiredLevel=32,faction="horde",expansion=3,zoneID=616,description="The Guardians of Hyjal, led by Arch Druid Malfurion Stormrage, seek brave heroes to assist with a full-scale assault on the Firelands. Willing and able-bodied champions of the Horde should report to the Sanctuary of Malorne in Mount Hyjal immediately.",starts={{npcID=206109,x=0.497,y=0.766,zoneID=1637},{npcID=206116,x=0.664,y=0.492,zoneID=1637},{npcID=207323,x=0.425,y=0.578,zoneID=1638},{npcID=207324,x=0.659,y=0.497,zoneID=1497},{npcID=207324,x=0.484,y=0.428,zoneID=7004}},ends={{npcID=52669,x=0.272,y=0.624,zoneID=616}},coords={x=0.497,y=0.766,source="quest_giver",zoneID=1637},questType="standard"},
[29389] = {id=29389,name="Guardians of Hyjal: Firelands Invasion!",level=32,requiredLevel=32,faction="both",expansion=3,zoneID=616,description="Your work has given us the advantage we need to mobilize against the denizens of the Firelands. We are gathering our invasion force just south of our position. We could use your strength again, . Speak with Matoclaw at the Sanctuary of Malorne. She is coordinating the invasion effort.",starts={{npcID=52838,x=0.27,y=0.546,zoneID=616}},ends={{npcID=52669,x=0.272,y=0.624,zoneID=616}},coords={x=0.27,y=0.546,source="quest_giver",zoneID=616},questType="standard"},
[29390] = {id=29390,name="Guardians of Hyjal: Call of the Ancients",level=32,requiredLevel=32,faction="horde",expansion=3,zoneID=7004,starts={{npcID=206109,x=0.497,y=0.766,zoneID=1637},{npcID=206116,x=0.664,y=0.492,zoneID=1637},{npcID=207323,x=0.425,y=0.578,zoneID=1638},{npcID=207324,x=0.659,y=0.497,zoneID=1497},{npcID=207324,x=0.484,y=0.428,zoneID=7004}},coords={x=0.497,y=0.766,source="quest_giver",zoneID=1637},questType="standard"},
[29392] = {id=29392,name="Missing Heirlooms",level=1,requiredLevel=1,faction="alliance",expansion=3,zoneID=1519,description="The last of my belongings were supposed to be arriving from Theramore today. The ship has arrived, but I haven't heard from the courier. The crate he was transporting had items that've been in my family for generations. Will you go down to Stormwind Harbor and see what's keeping him?",starts={{npcID=53949,x=0.602,y=0.752,zoneID=1519}},ends={{npcID=53950,x=0.24,y=0.446,zoneID=1519}},coords={x=0.602,y=0.752,source="quest_giver",zoneID=1519},questType="standard"},
[29394] = {id=29394,name="Brew For Brewfest",level=1,requiredLevel=1,faction="alliance",expansion=3,zoneID=1,starts={{npcID=23558,x=0.536,y=0.386,zoneID=1}},ends={{npcID=23558,x=0.536,y=0.386,zoneID=1}},coords={x=0.536,y=0.386,source="quest_giver",zoneID=1},questType="standard"},
[29396] = {id=29396,name="A New Supplier of Souvenirs",level=1,requiredLevel=1,faction="horde",expansion=3,zoneID=14,description="Don't talk to me about last year's stein... I think our shady stein suppliers were somehow involved with that Twilight Hammer cult non-sense that errupted just before the elementals invaded. And that's why we have a new supplier and a better stein! Here's a voucher for one. Talk to Blix near the back of the Brewfest camp. He's pretty strange, even more so now that he's always wearing those goggles. He'll handle the voucher for you, and any other Brewfest transaction.",starts={{npcID=24510,x=0.426,y=0.176,zoneID=14}},ends={{npcID=24495,x=0.404,y=0.178,zoneID=14}},coords={x=0.426,y=0.176,source="quest_giver",zoneID=14},questType="standard"},
[29397] = {id=29397,name="A New Supplier of Souvenirs",level=1,requiredLevel=1,faction="alliance",expansion=3,zoneID=1,description="The less said about last year's stein, the better, . I'll tell you this, our previous supplier, they were shady. Turns out they were involved in some cultist activities... We can't work with people who are trying to destroy the world!! So we have a new supplier and a new stein. Take this voucher to Belbi Quikswitch near the back of the Brewfest camp. She'll give you your free Brewfest stein. She'll also handle any and all other Brewfest transactions that come up during the holiday.",starts={{npcID=24468,x=0.536,y=0.386,zoneID=1}},ends={{npcID=23710,x=0.562,y=0.378,zoneID=1}},coords={x=0.536,y=0.386,source="quest_giver",zoneID=1},questType="standard"},
[29398] = {id=29398,name="Fencing the Goods",level=1,requiredLevel=1,faction="alliance",expansion=3,zoneID=1519,description="A quick search of the cabin reveals no evidence of the killer's identity or motives. The crate you were sent to retrieve has vanished. As you turn to leave the cabin, you notice something small moving underfoot. A trail of spiders crawls out from under the slain courier's bed. Where could they be heading?",starts={{npcID=53950,x=0.24,y=0.446,zoneID=1519}},ends={{npcID=8719,x=0.612,y=0.708,zoneID=1519}},coords={x=0.24,y=0.446,source="quest_giver",zoneID=1519},questType="standard"},
[29399] = {id=29399,name="Shopping Around",level=1,requiredLevel=1,faction="alliance",expansion=3,zoneID=1519,description="I told the 'gentleman' that there might be a shop more suited to his needs in the Dwarven District. It's called the Shady Lady and you can find the entrance near the Canals on the western side of the district. Quincy Cutler is your man. He trades in merchandise an honest broker would never touch!",starts={{npcID=8719,x=0.612,y=0.708,zoneID=1519}},ends={{npcID=54021,x=0.64,y=0.464,zoneID=1519}},coords={x=0.612,y=0.708,source="quest_giver",zoneID=1519},questType="standard"},
[30111] = {id=30111,name="LFGDungeons - Cataclysm - Raid Finder - Nth",level=35,requiredLevel=35,faction="none",expansion=3,questType="standard"},
}
end)
